
// V20: make failed API calls visible instead of leaving a permanent spinner.
window.addEventListener('unhandledrejection', function(ev) {
  const msg = ev && ev.reason && ev.reason.message ? ev.reason.message : String(ev.reason || 'Unknown error');
  console.error('Unhandled promise rejection:', msg);
});

const root=document.getElementById('root');let unreadNotifCount=0;let token=localStorage.getItem('bo_token'),me=null,view='dashboard',unitOptions=[],selectedUnitId=localStorage.getItem('bo_unit')||'';
const roles=['CEO / Owner','Operations Manager','Finance / Admin','Sales / Business Development','Business Unit Manager','Staff Member'];
const nav=[['dashboard','Dashboard'],['businesses','Business Units'],['sales','Sales'],['purchases','Purchases'],['inventory','Inventory'],['finance','Finance'],['approvals','Approvals'],['tasks','Tasks'],['crm','CRM'],['reports','Daily Reports'],['kpi','KPIs'],['documents','Documents'],['meetings','Meetings'],['restaurantTables','Restaurant Tables'],['restaurant','MIMI POS'],['excavator','Excavator Operations'],['excavatorSuppliers','Suppliers'],['excavatorBuyers','Buyers'],['notifications','Notifications'],['users','Users'],['profile','My Profile'],['audit','Audit']];
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));}
function money(v){return Number(v||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});}
async function api(url,opt={}){opt.headers=opt.headers||{};if(token)opt.headers.Authorization='Bearer '+token;if(me?.role==='CEO / Owner' && selectedUnitId)opt.headers['X-Business-Unit-ID']=selectedUnitId;else if(me?.role!=='CEO / Owner' && me?.business_unit_id)opt.headers['X-Business-Unit-ID']=me.business_unit_id;const r=await fetch(url,opt);let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||'Request failed');return d;}
function toast(m){const e=document.createElement('div');e.className='toast';e.textContent=m;document.getElementById('toastRoot').appendChild(e);setTimeout(()=>e.remove(),2800)}
function modal(html){document.getElementById('modalRoot').innerHTML='<div class="modal-bg" onclick="if(event.target===this)closeModal()"><div class="modal">'+html+'</div></div>'}
function closeModal(){document.getElementById('modalRoot').innerHTML=''}

async function refreshNotifCount(){try{const d=await api('/api/notifications/unread-count');unreadNotifCount=Number(d.count||0);const b=document.getElementById('notifBadge');if(b){b.textContent=unreadNotifCount;b.style.display=unreadNotifCount?'inline-flex':'none'}}catch(e){console.warn('Notification count:',e.message)}}
function closeNotifDialog(){const e=document.getElementById('notifDialog');if(e)e.remove()}
setInterval(refreshNotifCount,30000);
async function toggleNotifs(){closeNotifDialog();try{const n=await api('/api/notifications');const unread=n.filter(x=>!x.read_at).length;const wrap=document.createElement('div');wrap.id='notifDialog';wrap.className='modal-bg';wrap.innerHTML='<div class="modal" style="max-width:620px"><div class="section-title"><div><h2 style="margin:0">Notifications</h2><div class="muted">'+unread+' unread notification'+(unread===1?'':'s')+'</div></div><button class="btn" onclick="closeNotifDialog()">✕</button></div><div style="max-height:60vh;overflow:auto;margin-top:12px">'+(n.length?n.map(x=>'<div class="card" style="margin-bottom:8px"><span class="pill '+(x.level==='critical'?'bad':x.level==='warning'?'warn':'blue')+'">'+esc(x.level||'info')+'</span> <b>'+esc(x.title||'Notification')+'</b><div class="muted" style="margin-top:4px">'+esc(x.message||'')+'</div><div class="muted" style="font-size:12px;margin-top:5px">'+esc(x.created_at||'')+'</div>'+(!x.read_at?'<button class="btn small" style="margin-top:7px" onclick="readNotif('+x.id+').then(toggleNotifs)">Mark read</button>':'')+'</div>').join(''):'<div class="empty">No notifications.</div>')+'</div></div>';document.body.appendChild(wrap);wrap.onclick=e=>{if(e.target===wrap)closeNotifDialog()}}catch(e){toast(e.message)}}
function allowed(key){if(!me)return false;if(me.role==='CEO / Owner')return true;const map={dashboard:1,businesses:['Operations Manager'],sales:['Operations Manager','Finance / Admin','Sales / Business Development','Business Unit Manager'],purchases:['Operations Manager','Finance / Admin','Business Unit Manager'],inventory:['Operations Manager','Finance / Admin','Business Unit Manager','Staff Member'],finance:['Operations Manager','Finance / Admin','Business Unit Manager'],approvals:['Operations Manager','Finance / Admin','Business Unit Manager'],tasks:['Operations Manager','Sales / Business Development','Business Unit Manager','Staff Member'],crm:['Operations Manager','Sales / Business Development','Business Unit Manager'],reports:['Operations Manager','Finance / Admin','Business Unit Manager','Staff Member'],kpi:['Operations Manager','Sales / Business Development','Business Unit Manager'],documents:['Operations Manager','Finance / Admin','Sales / Business Development','Business Unit Manager','Staff Member'],meetings:['Operations Manager','Business Unit Manager'],restaurant:['Operations Manager','Business Unit Manager'],excavator:['Operations Manager','Finance / Admin','Sales / Business Development','Business Unit Manager'],excavatorBuyers:['Operations Manager','Finance / Admin','Sales / Business Development','Business Unit Manager'],users:['Operations Manager'],audit:['Operations Manager']};return map[key]===1||map[key]?.includes(me.role)||['notifications','profile'].includes(key)}
function login(){root.innerHTML=`<div class="login"><div class="login-card"><div class="brand">BLUE OCEAN <span>MARKET</span></div><h1>Management OS</h1><p class="sub">Company-wide operations, finance, inventory, sales and restaurant control.</p><form onsubmit="doLogin(event)"><div class="field"><label>Email</label><input name="email" type="email" value="admin@blueocean.local" required></div><div class="field"><label>Password</label><input name="password" type="password" value="Admin@123" required></div><button class="btn primary" style="width:100%;padding:12px">Sign in</button></form><button class="btn" style="width:100%;margin-top:10px" onclick="forgot()">Forgot password?</button><p class="sub" style="margin-top:14px">Demo administrator: admin@blueocean.local / Admin@123</p></div></div>`}
async function doLogin(e){e.preventDefault();try{const d=await api('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});token=d.token;me=d.user;localStorage.setItem('bo_token',token);selectedUnitId=me.role==='CEO / Owner'?(localStorage.getItem('bo_unit')||''):String(me.business_unit_id||'');const ctx=await api('/api/context');unitOptions=ctx.units||[];render();}catch(x){toast(x.message)}}
function forgot(){modal(`<h2>Reset password</h2><p class="muted">Enter the account email. In this self-contained build the reset URL is returned directly for testing; connect SMTP for production email delivery.</p><form onsubmit="doForgot(event)"><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Create reset link</button></div></form>`)}
async function doForgot(e){e.preventDefault();try{const d=await api('/api/auth/forgot',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});modal(`<h2>Reset link</h2><p class="muted">For local testing, open this link:</p><input value="${esc(d.reset_url||'No reset URL returned')}" style="width:100%;padding:10px"><div class="actions"><button class="btn primary" onclick="closeModal()">Done</button></div>`)}catch(x){toast(x.message)}}
function navButton(x){return `<button class="${view===x[0]?'active':''}" onclick="go('${x[0]}')">${x[1]}</button>`}
function render(){
  const selected=unitOptions.find(x=>String(x.id)===String(selectedUnitId));
  const isExcavator=selected?.name==='Excavator';
  const visible=x=>allowed(x[0]) && (x[0]!=='restaurant'&&x[0]!=='restaurantTables'||selected?.name==='MIMI Resturant') && (x[0]!=='excavator'&&x[0]!=='excavatorSuppliers'&&x[0]!=='excavatorBuyers'||isExcavator);
  const excavatorKeys=['dashboard','excavator','excavatorSuppliers','excavatorBuyers','finance','documents','notifications'];
  const excavatorNav=[['dashboard','Dashboard'],['excavator','Operations'],['excavatorSuppliers','Suppliers'],['excavatorBuyers','Buyers'],['finance','Finance'],['documents','Documents'],['notifications','Notifications']].filter(visible);
  const generalNav=nav.filter(x=>visible(x)&&!excavatorKeys.includes(x[0]));
  let navHtml='';
  if(isExcavator){
    navHtml='<div class="nav-section"><div class="nav-section-title">EXCAVATOR</div>'+excavatorNav.map(navButton).join('')+'</div>'+
      '<div class="nav-separator"></div><div class="nav-section"><div class="nav-section-title">OTHER SYSTEM MODULES</div>'+generalNav.map(navButton).join('')+'</div>';
  }else navHtml=nav.filter(visible).map(navButton).join('');
  const unitSelect=me.role==='CEO / Owner'
    ? '<select class="unit-switch" onchange="switchUnit(this.value)"><option value="">All Business Units — Consolidated</option>'+unitOptions.map(x=>`<option value="${x.id}" ${String(selectedUnitId)===String(x.id)?'selected':''}>${esc(x.name)}</option>`).join('')+'</select>'
    : `<span class="scope-badge">${esc(selected?.name||'Assigned Business Unit')}</span>`;
  root.innerHTML='<div class="shell"><aside class="side"><div class="brand">BLUE OCEAN <span>MARKET</span></div><nav class="nav">'+navHtml+'</nav></aside><main class="main"><header class="top"><div><b>'+esc(me.name)+'</b><span class="muted role"> · '+esc(me.role)+'</span></div><div class="top-right">'+unitSelect+'<button class="notif-btn" onclick="toggleNotifs()" title="Notifications">🔔<span id="notifBadge" class="notif-badge" style="display:none">0</span></button><div class="avatar">'+esc(me.name.slice(0,1).toUpperCase())+'</div><button class="btn" onclick="logout()">Logout</button></div></header><section class="content" id="content"></section></main></div>';
  loadView();refreshNotifCount();
}
function go(v){view=v;render()}
function logout(){localStorage.removeItem('bo_token');token=null;me=null;login()}
async function boot(){if(!token)return login();try{me=(await api('/api/me')).user;const ctx=await api('/api/context');unitOptions=ctx.units||[];if(me.role!=='CEO / Owner')selectedUnitId=String(me.business_unit_id||'');else if(selectedUnitId && !unitOptions.some(x=>String(x.id)===String(selectedUnitId)))selectedUnitId='';render()}catch(e){logout()}}
async function switchUnit(id){selectedUnitId=id||'';if(selectedUnitId)localStorage.setItem('bo_unit',selectedUnitId);else localStorage.removeItem('bo_unit');if(view==='restaurant'&& !unitOptions.find(x=>String(x.id)===String(selectedUnitId) && x.name==='MIMI Resturant'))view='dashboard';render();}
async function loadView(){const c=document.getElementById('content');c.innerHTML='<div class="card">Loading…</div>';try{if(view==='dashboard'){const selected=unitOptions.find(x=>String(x.id)===String(selectedUnitId));if(selected?.name==='Excavator')return excavatorDashboard(c);if(selected?.name==='MIMI Resturant')return mimiDashboard(c);return dashboard(c);}if(view==='businesses')return businesses(c);if(view==='sales')return sales(c);if(view==='purchases')return purchases(c);if(view==='inventory')return inventory(c);if(view==='finance')return finance(c);if(view==='approvals')return approvals(c);if(view==='tasks')return tasks(c);if(view==='crm')return crm(c);if(view==='reports')return reports(c);if(view==='kpi')return kpis(c);if(view==='documents')return documents(c);if(view==='meetings')return meetings(c);if(view==='restaurantTables')return restaurantTables(c);if(view==='restaurant')return restaurant(c);if(view==='excavator')return excavator(c);if(view==='excavatorSuppliers')return excavatorSuppliers(c);if(view==='excavatorBuyers')return excavatorBuyers(c);if(view==='notifications')return notificationsView(c);if(view==='users')return users(c);if(view==='profile')return profileView(c);if(view==='audit')return auditView(c)}catch(e){c.innerHTML='<div class="card"><b>Error</b><p class="muted">'+esc(e.message)+'</p></div>'}}
function title(t,s,btn=''){return `<div class="titlebar"><div><h1>${t}</h1><div class="muted">${s||''}</div></div>${btn}</div>`}
async function dashboard(c){
  const selected=unitOptions.find(x=>String(x.id)===String(selectedUnitId));
  if(!selected) return ceoDashboard(c);
  if(selected.name==='MIMI Resturant') return mimiDashboard(c);
  if(selected.name==='Excavator') return excavatorDashboard(c);
  return unitDashboard(c, selected);
}
async function ceoDashboard(c){
  try{const [d,ts]=await Promise.all([api('/api/dashboard'),api('/api/dashboard/timeseries')]);
  c.innerHTML=title('CEO — Consolidated Dashboard','All Business Units · consolidated management view')+`<div class="workspace-banner"><b>CEO Command Center</b><span>Select a business from the top Workspace selector to open that unit's dashboard.</span></div><div class="grid g4"><div class="card stat"><div class="label">Revenue</div><div class="value">${money(d.revenue)}</div></div><div class="card stat"><div class="label">Expenses</div><div class="value">${money(d.expenses)}</div></div><div class="card stat"><div class="label">Net</div><div class="value">${money(d.net)}</div></div><div class="card stat"><div class="label">Gross Profit</div><div class="value">${money(d.gross_profit)}</div></div></div><div class="grid g3" style="margin-top:16px"><div class="card"><h3>Approvals</h3><div class="big-number">${d.pending}</div></div><div class="card"><h3>Overdue Tasks</h3><div class="big-number">${d.overdue}</div></div><div class="card"><h3>Low Stock</h3><div class="big-number">${d.low}</div></div></div><div class="card" style="margin-top:16px"><div class="section-title"><h3>Business Unit Performance</h3></div><div class="table-wrap"><table class="table"><tr><th>Business Unit</th><th>Sales</th><th>Gross Profit</th><th>Expenses</th><th>Inventory</th></tr>${d.units.map(u=>`<tr><td><b>${esc(u.name)}</b></td><td>${money(u.sales)}</td><td>${money(u.gross_profit)}</td><td>${money(u.expenses)}</td><td>${money(u.inventory_value)}</td></tr>`).join('')}</table></div></div>`;
  }catch(e){dashboardError(c,e)}
}
async function mimiDashboard(c){
  try{const [tables,menu,buffets,orders,sales]=await Promise.all([api('/api/restaurant/tables'),api('/api/restaurant/menu'),api('/api/restaurant/buffets'),api('/api/restaurant/orders'),api('/api/sales')]);
    const open=orders.filter(x=>x.status==='Open').length, available=tables.filter(x=>x.status==='Available').length, busy=tables.filter(x=>x.status==='Busy').length, published=buffets.filter(x=>x.status==='Published').length;
    const revenue=sales.reduce((a,x)=>a+Number(x.total||0),0), profit=sales.reduce((a,x)=>a+Number(x.gross_profit||0),0);
    c.innerHTML=title('MIMI Resturant — Dashboard','Restaurant workspace · only MIMI data is shown',`<button class="btn primary" onclick="go('restaurant')">Open POS</button>`)+`<div class="workspace-banner"><b>MIMI Resturant</b><span>Restaurant Tables manages tables. POS only uses tables for dine-in orders.</span></div><div class="grid g4"><div class="card stat"><div class="label">Today / visible sales</div><div class="value">₩ ${money(revenue)}</div></div><div class="card stat"><div class="label">Gross Profit</div><div class="value">₩ ${money(profit)}</div></div><div class="card stat"><div class="label">Open Orders</div><div class="value">${open}</div></div><div class="card stat"><div class="label">Available Tables</div><div class="value">${available}</div><div class="hint">${busy} occupied</div></div></div><div class="grid g3" style="margin-top:16px"><div class="card"><h3>Menu</h3><div class="big-number">${menu.filter(x=>x.active).length}</div><p class="muted">Active menu items</p><button class="btn" onclick="go('restaurant')">Menu / POS</button></div><div class="card"><h3>Published Buffets</h3><div class="big-number">${published}</div><p class="muted">Visible in POS</p><button class="btn" onclick="go('restaurant')">Open POS</button></div><div class="card"><h3>Restaurant Tables</h3><div class="big-number">${tables.length}</div><p class="muted">${available} available · ${busy} occupied</p><button class="btn" onclick="go('restaurantTables')">Manage Tables</button></div></div><div class="card" style="margin-top:16px"><div class="section-title"><h3>Open Orders</h3><button class="btn small" onclick="go('restaurant')">Open POS</button></div>${orders.filter(x=>x.status==='Open').slice(0,8).map(o=>`<div class="order-row"><span><b>${esc(o.order_no)}</b> · ${esc(o.order_type)} ${o.table_name?'· '+esc(o.table_name):''}</span><span>${esc(o.created_at)}</span></div>`).join('')||'<div class="empty">No open orders.</div>'}</div>`;
  }catch(e){dashboardError(c,e)}
}
async function excavatorDashboard(c){
  try{const d=await api('/api/excavator/overview'),s=d.summary||{};
    c.innerHTML=title('Excavator — Dashboard','South Korea used-machine business · base currency KRW',`<button class="btn primary" onclick="go('excavator')">Open Excavator Operations</button>`)+`<div class="workspace-banner"><b>Excavator Workspace</b><span>One machine/deal remains open from purchase through local sale or export and can be resumed later.</span></div><div class="grid g4"><div class="card stat"><div class="label">Open Machines</div><div class="value">${s.open||0}</div></div><div class="card stat"><div class="label">In Yard</div><div class="value">${s.inYard||0}</div></div><div class="card stat"><div class="label">Under Repair</div><div class="value">${s.repairing||0}</div></div><div class="card stat"><div class="label">Ready for Sale</div><div class="value">${s.ready||0}</div></div></div><div class="grid g4" style="margin-top:16px"><div class="card stat"><div class="label">Purchase Cost</div><div class="value">₩ ${money(s.purchase)}</div></div><div class="card stat"><div class="label">Logistics</div><div class="value">₩ ${money(s.logistics)}</div></div><div class="card stat"><div class="label">Repairs + Parts</div><div class="value">₩ ${money(Number(s.repair||0)+Number(s.partCost||0))}</div></div><div class="card stat"><div class="label">Gross Margin</div><div class="value">₩ ${money(s.margin)}</div></div></div><div class="grid g3" style="margin-top:16px"><div class="card"><h3>Lifecycle</h3>${(d.stages||[]).map(st=>`<div class="order-row"><span>${esc(st)}</span><b>${(d.assets||[]).filter(a=>a.lifecycle_stage===st).length}</b></div>`).join('')}</div><div class="card"><h3>Cost Structure</h3>${[['Purchase',s.purchase],['Logistics',s.logistics],['Repair',s.repair],['Parts',s.partCost],['Other',s.other]].map(x=>`<div class="order-row"><span>${x[0]}</span><b>₩ ${money(x[1])}</b></div>`).join('')}</div><div class="card"><h3>Open Work</h3><p class="muted">Purchase, transport, repairs, parts, local sale/export and payments remain separate entries linked to the same machine.</p><button class="btn" onclick="go('excavator')">Continue Machines</button></div></div>`;
  }catch(e){dashboardError(c,e)}
}
async function unitDashboard(c,selected){
 try{const d=await api('/api/dashboard');c.innerHTML=title(`${esc(selected.name)} — Dashboard`,`Only ${esc(selected.name)} data is shown`, '')+`<div class="workspace-banner"><b>Selected workspace: ${esc(selected.name)}</b><span>All dashboard figures and modules are scoped to this business unit.</span></div><div class="grid g4"><div class="card stat"><div class="label">Revenue</div><div class="value">${money(d.revenue)}</div></div><div class="card stat"><div class="label">Expenses</div><div class="value">${money(d.expenses)}</div></div><div class="card stat"><div class="label">Net</div><div class="value">${money(d.net)}</div></div><div class="card stat"><div class="label">Gross Profit</div><div class="value">${money(d.gross_profit)}</div></div></div>`;}catch(e){dashboardError(c,e)}
}
function dashboardError(c,e){c.innerHTML=title('Dashboard','Unable to load the selected workspace dashboard')+`<div class="card"><b>Dashboard could not be loaded.</b><p class="muted">${esc(e.message)}</p><button class="btn primary" onclick="loadView()">Retry</button></div>`}
async function businesses(c){const b=await api('/api/business-units'),p=await api('/api/pnl');c.innerHTML=title('Business Units','Each unit is an independent workspace; CEO can switch the active unit from the top bar',allowed('businesses')?'<button class="btn primary" onclick="businessForm()">+ Add business</button>':'')+`<div class="grid g3">${b.map(x=>{const z=p.find(y=>y.id===x.id)||{};return `<div class="card"><div class="section-title"><h3>${esc(x.name)}</h3><span class="pill ${x.status==='Active'?'good':'warn'}">${x.status}</span></div><div class="muted">Manager: ${esc(x.manager_name||'Unassigned')}</div><div class="grid g2" style="margin-top:14px"><div><small>Sales</small><b>${money(z.sales)}</b></div><div><small>Net profit</small><b>${money(z.net_profit)}</b></div><div><small>Gross profit</small><b>${money(z.gross_profit)}</b></div><div><small>Expenses</small><b>${money(z.operating_expense)}</b></div></div><div class="actions" style="margin-top:14px"><button class="btn small" onclick="editBusiness(${x.id})">Edit</button> <button class="btn small danger" onclick="deleteBusiness(${x.id})">Delete</button></div></div>`}).join('')}</div>`}
async function businessForm(id){const b=id?await api('/api/business-units/'+id):null;const users=await api('/api/users');modal(`<h2>${id?'Manage':'Add'} business unit</h2><form onsubmit="saveBusiness(event,${id||0})"><div class="field"><label>Name</label><input name="name" value="${esc(b?.name||'')}" required></div><div class="grid g2"><div class="field"><label>Manager</label><select name="manager_id"><option value="">Unassigned</option>${users.map(u=>`<option value="${u.id}" ${b?.manager_id==u.id?'selected':''}>${esc(u.name)}</option>`).join('')}</select></div><div class="field"><label>Lifecycle Stage</label><select name="lifecycle_stage">${['Purchased','Transport to Yard','In Yard','Under Repair','Ready for Sale','Local Sale','Export Preparation','Exported','Sold','Completed','On Hold','Cancelled'].map(z=>`<option ${x?.lifecycle_stage===z?'selected':''}>${z}</option>`).join('')}</select></div><div class="field"><label>Status</label><select name="status"><option ${b?.status==='Active'?'selected':''}>Active</option><option ${b?.status==='Paused'?'selected':''}>Paused</option><option ${b?.status==='Closed'?'selected':''}>Closed</option></select></div></div><div class="field"><label>Notes</label><textarea name="notes">${esc(b?.notes||'')}</textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save</button></div></form>`)}
async function editBusiness(id){businessForm(id)}
async function saveBusiness(e,id){e.preventDefault();const o=Object.fromEntries(new FormData(e.target));try{await api(id?'/api/business-units/'+id:'/api/business-units',{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});closeModal();toast('Business saved');loadView()}catch(x){toast(x.message)}}
async function deleteBusiness(id){if(!confirm('Delete this business unit? Historical units cannot be deleted; close them instead.'))return;try{await api('/api/business-units/'+id,{method:'DELETE'});toast('Business deleted');loadView()}catch(x){toast(x.message)}}
async function sales(c){const rows=await api('/api/sales');c.innerHTML=title('Sales','Product and service sales with cost, gross profit and receipts','<button class="btn primary" onclick="saleForm()">+ New Sale</button>')+`<div class="card"><div class="table-wrap"><table class="table"><tr><th>Invoice</th><th>Business</th><th>Customer</th><th>Type</th><th>Total</th><th>Cost</th><th>Gross profit</th><th>Payment</th><th>Date</th><th>Actions</th></tr>${rows.map(x=>`<tr><td><b>${esc(x.invoice_no)}</b></td><td>${esc(x.business_unit)}</td><td>${esc(x.customer_name||'Walk-in')}</td><td>${esc(x.order_type)}</td><td>${money(x.total)}</td><td>${money(x.cost_total)}</td><td><span class="pill ${x.gross_profit>=0?'good':'bad'}">${money(x.gross_profit)}</span></td><td>${esc(x.payment_method)}</td><td>${x.created_at}</td><td><button class="btn small" onclick="printReceipt(${x.id})">🧾 Print</button> <button class="btn small danger" onclick="voidSale(${x.id})">Void</button></td></tr>`).join('')}</table></div></div>`}
async function voidSale(id){if(!confirm('Void this sale? It will remain in history.'))return;try{await api('/api/sales/'+id+'/void',{method:'PUT'});toast('Sale voided');loadView()}catch(x){toast(x.message)}}
async function saleForm(){const [u,p]=await Promise.all([api('/api/business-units'),api('/api/products')]);let items=[];modal(`<h2>New product / service sale</h2><form onsubmit="saveSale(event)"><div class="grid g2"><div class="field"><label>Business unit</label><select id="saleUnit" name="business_unit_id" onchange="filterSaleProducts()" required>${u.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Payment method</label><select name="payment_method"><option>Cash</option><option>Card</option><option>Bank</option><option>Credit</option><option>Other</option></select></div></div><div class="grid g2"><div class="field"><label>Customer</label><input name="customer_name" placeholder="Walk-in / customer"></div><div class="field"><label>Discount</label><input name="discount" type="number" step="0.01" value="0"></div></div><div class="field"><label>Add item</label><select id="saleProduct" onchange="addSaleItem(this.value)"><option value="">Select product/service</option>${p.map(x=>`<option data-unit="${x.business_unit_id}" value="${x.id}">${esc(x.name)} — ${esc(x.business_unit)} — ${money(x.selling_price)}</option>`).join('')}</select></div><div id="saleItems" class="card" style="background:#fafcff"></div><input type="hidden" name="items" id="saleItemsInput"><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Complete sale</button></div></form>`);window._saleProducts=p;window._saleItems=items;drawSaleItems()}
function filterSaleProducts(){const id=document.getElementById('saleUnit').value;document.querySelectorAll('#saleProduct option[data-unit]').forEach(o=>o.hidden=o.dataset.unit!==id)}
function addSaleItem(id){if(!id)return;const p=window._saleProducts.find(x=>x.id==id);let x=window._saleItems.find(x=>x.product_id==id);if(x)x.quantity++;else window._saleItems.push({product_id:p.id,name:p.name,quantity:1,unit_price:p.selling_price});drawSaleItems();document.getElementById('saleProduct').value=''}
function drawSaleItems(){const el=document.getElementById('saleItems');if(!el)return;el.innerHTML=window._saleItems.length?window._saleItems.map((x,i)=>`<div class="cart-row"><span>${esc(x.name)}</span><span><input style="width:70px" type="number" min="1" value="${x.quantity}" onchange="window._saleItems[${i}].quantity=Number(this.value)"> × ${money(x.unit_price)} <button type="button" class="btn small" onclick="window._saleItems.splice(${i},1);drawSaleItems()">×</button></span></div>`).join(''):'<span class="muted">No items added.</span>'}
async function saveSale(e){e.preventDefault();const f=new FormData(e.target),o=Object.fromEntries(f);o.items=window._saleItems;if(!o.items.length)return toast('Add at least one item');delete o.itemsInput;try{const d=await api('/api/sales',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});closeModal();toast(`Sale ${d.invoice} completed · Profit ${money(d.gross_profit)}`);loadView();printReceipt(d.id)}catch(x){toast(x.message)}}
async function purchases(c){const rows=await api('/api/purchases');c.innerHTML=title('Purchases','Buy stock/services by business unit; costs flow into finance and inventory','<button class="btn primary" onclick="purchaseForm()">+ New Purchase</button>')+`<div class="card"><div class="table-wrap"><table class="table"><tr><th>Purchase</th><th>Business</th><th>Supplier</th><th>Total</th><th>Payment</th><th>Status</th><th>Date</th><th>Actions</th></tr>${rows.map(x=>`<tr><td>${esc(x.purchase_no)}</td><td>${esc(x.business_unit)}</td><td>${esc(x.supplier_name)}</td><td>${money(x.total)}</td><td>${esc(x.payment_method)}</td><td>${esc(x.status)}</td><td>${x.created_at}</td><td><button class="btn small" onclick="purchaseEdit(${x.id})">Edit</button> <button class="btn small danger" onclick="voidPurchase(${x.id})">Void</button></td></tr>`).join('')}</table></div></div>`}
async function purchaseForm(){const [u,p]=await Promise.all([api('/api/business-units'),api('/api/products')]);modal(`<h2>New purchase</h2><form onsubmit="savePurchase(event)"><div class="grid g2"><div class="field"><label>Business</label><select name="business_unit_id" id="purUnit" required>${u.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Supplier</label><input name="supplier_name"></div></div><div class="field"><label>Items</label><select id="purProduct" onchange="addPurItem(this.value)"><option value="">Select product</option>${p.filter(x=>x.item_type==='PRODUCT').map(x=>`<option value="${x.id}">${esc(x.name)} — ${esc(x.business_unit)}</option>`).join('')}</select></div><div id="purItems" class="card"></div><div class="grid g2"><div class="field"><label>Payment</label><select name="payment_method"><option>Cash</option><option>Card</option><option>Bank</option><option>Credit</option></select></div><div class="field"><label>Attachment</label><input name="attachment" type="file"></div></div><div class="field"><label>Notes</label><textarea name="notes">${esc(existing?.notes||'')}</textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Receive purchase</button></div></form>`);window._purProducts=p;window._purItems=[];drawPurItems()}
function addPurItem(id){if(!id)return;const p=window._purProducts.find(x=>x.id==id);let x=window._purItems.find(x=>x.product_id==id);if(x)x.quantity++;else window._purItems.push({product_id:p.id,name:p.name,quantity:1,unit_cost:p.cost_price});drawPurItems()}
function drawPurItems(){const e=document.getElementById('purItems');if(!e)return;e.innerHTML=window._purItems.length?window._purItems.map((x,i)=>`<div class="cart-row"><span>${esc(x.name)}</span><span><input style="width:65px" type="number" min="1" value="${x.quantity}" onchange="window._purItems[${i}].quantity=Number(this.value)"> × <input style="width:100px" type="number" value="${x.unit_cost}" onchange="window._purItems[${i}].unit_cost=Number(this.value)"> <button type="button" class="btn small" onclick="window._purItems.splice(${i},1);drawPurItems()">×</button></span></div>`).join(''):'<span class="muted">No items.</span>'}
async function savePurchase(e){e.preventDefault();if(!window._purItems.length)return toast('Add at least one product');const fd=new FormData(e.target);fd.set('items',JSON.stringify(window._purItems));try{await api('/api/purchases',{method:'POST',body:fd});closeModal();toast('Purchase received; stock and finance updated');loadView()}catch(x){toast(x.message)}}
async function inventory(c){try{const d=await api('/api/inventory/summary');const m=await api('/api/inventory/movements');const rows=d.rows||[];c.innerHTML=title('Inventory','Complete stock master, valuation, reorder control and stock movement history',allowed('inventory')?'<button class="btn primary" onclick="productForm()">+ Add product/service</button>':'')+`<div class="grid g4"><div class="card stat"><div class="label">Items</div><div class="value">${d.products.items||0}</div></div><div class="card stat"><div class="label">Stock Value</div><div class="value">${money(d.products.value||0)}</div></div><div class="card stat"><div class="label">Low Stock</div><div class="value">${d.products.low||0}</div></div><div class="card stat"><div class="label">Out of Stock</div><div class="value">${d.products.out||0}</div></div></div><div class="card" style="margin-top:16px"><div class="section-title"><h3>Stock Master</h3></div>${rows.length?`<div class="table-wrap"><table class="table"><tr><th>Business</th><th>SKU</th><th>Item</th><th>Stock</th><th>Reorder</th><th>Cost</th><th>Sell</th><th>Actions</th></tr>${rows.map(x=>`<tr><td>${esc(x.business_unit)}</td><td>${esc(x.sku)}</td><td>${esc(x.name)}</td><td><b>${money(x.current_stock)} ${esc(x.unit)}</b></td><td>${money(x.reorder_level)}</td><td>${money(x.cost_price)}</td><td>${money(x.selling_price)}</td><td>${allowed('inventory')?`<button class="btn small" onclick="productForm(${x.id})">Edit</button> <button class="btn small" onclick="moveStock(${x.id},'ADD')">Add</button> <button class="btn small" onclick="moveStock(${x.id},'REMOVE')">Remove</button>`:''}</td></tr>`).join('')}</table></div>`:'<div class="empty">No inventory items are available in the selected business scope.</div>'}</div><div class="card" style="margin-top:16px"><div class="section-title"><h3>Recent Stock Movements</h3></div>${m.length?`<div class="table-wrap"><table class="table"><tr><th>Date</th><th>Business</th><th>Item</th><th>Type</th><th>Qty</th><th>Reason</th><th>User</th></tr>${m.map(x=>`<tr><td>${x.created_at}</td><td>${esc(x.business_unit)}</td><td>${esc(x.product)}</td><td>${esc(x.type)}</td><td>${money(x.quantity)}</td><td>${esc(x.reason)}</td><td>${esc(x.user_name||'')}</td></tr>`).join('')}</table></div>`:'<div class="empty">No stock movements recorded yet.</div>'}</div>`}catch(e){c.innerHTML=title('Inventory','Unable to load inventory')+`<div class="card"><b>Inventory could not be loaded.</b><p class="muted">${esc(e.message)}</p><button class="btn primary" onclick="loadView()">Retry</button></div>`}}
async function moveStock(id,type){const q=prompt(type==='ADD'?'Quantity to add':'Quantity to remove','1');if(!q)return;const reason=prompt('Reason','Manual adjustment');try{await api('/api/inventory/move',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({product_id:id,type,quantity:q,reason})});toast('Inventory updated');loadView()}catch(x){toast(x.message)}}
async function finance(c){const [f,p]=await Promise.all([api('/api/finance'),api('/api/pnl')]);c.innerHTML=title('Finance & Profitability','Automatic machine transactions + manual entries · Finance verification','<button class="btn primary" onclick="financeForm()">+ Manual Finance Entry</button>')+`<div class="grid g3">${p.map(x=>`<div class="card"><b>${esc(x.name)}</b><div class="grid g2"><div><small>Revenue</small><b>${money(x.sales)}</b></div><div><small>COGS</small><b>${money(x.cogs)}</b></div><div><small>Gross</small><b>${money(x.gross_profit)}</b></div><div><small>Net</small><b>${money(x.net_profit)}</b></div></div></div>`).join('')}</div><div class="card" style="margin-top:16px"><div class="table-wrap"><table class="table"><tr><th>Date</th><th>Business</th><th>Source</th><th>Type</th><th>Category</th><th>Amount</th><th>Verification</th><th>Files</th><th>Actions</th></tr>${f.map(x=>`<tr><td>${x.created_at}</td><td>${esc(x.business_unit)}</td><td>${esc(x.source_type||'Manual')}</td><td>${x.type}</td><td>${esc(x.category)}</td><td>₩ ${money(x.amount)}</td><td><span class="pill ${x.verification_status==='Verified / Correct'?'good':x.verification_status==='Rejected / Incorrect'?'bad':'warn'}">${esc(x.verification_status||'Pending Verification')}</span></td><td>${x.attachment_count||0}</td><td>${me.role==='Finance / Admin'||me.role==='CEO / Owner'?`<button class="btn small" onclick="financeVerify(${x.id})">Verify</button>`:''} <button class="btn small" onclick="financeEdit(${x.id})">Edit</button> <button class="btn small danger" onclick="voidFinance(${x.id})">Void</button></td></tr>`).join('')}</table></div></div>`}
async function financeForm(){const u=await api('/api/business-units');modal(`<h2>Manual Finance Entry</h2><form onsubmit="saveFinance(event)" enctype="multipart/form-data"><div class="grid g2"><div class="field"><label>Business</label><select name="business_unit_id">${u.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Type</label><select name="type"><option>Expense</option><option>Revenue</option></select></div></div><div class="grid g2"><div class="field"><label>Category</label><select name="category"><option>General Expense</option><option>Salary / Wages</option><option>Rent</option><option>Utilities</option><option>Transport</option><option>Bank Charges</option><option>Other Expense</option><option>Other Income</option></select></div><div class="field"><label>Amount (KRW)</label><input name="amount" type="number" step="1" required></div></div><div class="grid g2"><div class="field"><label>Payment</label><select name="payment_method"><option>Bank</option><option>Cash</option><option>Card</option><option>Other</option></select></div><div class="field"><label>Due date</label><input name="due_date" type="date"></div></div><div class="grid g2"><div class="field"><label>Reference</label><input name="reference"></div><div class="field"><label>Attachments</label><input name="attachments" type="file" multiple></div></div><div class="field"><label>Description</label><textarea name="description" required></textarea></div><input type="hidden" name="source_type" value="Manual"><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save Entry</button></div></form>`)}
async function saveFinance(e){e.preventDefault();try{await api('/api/finance',{method:'POST',body:new FormData(e.target)});closeModal();toast('Finance entry saved · Pending Verification');loadView()}catch(x){toast(x.message)}}
async function financeVerify(id){modal(`<h2>Verify Finance Entry</h2><form onsubmit="saveFinanceVerify(event,${id})"><div class="field"><label>Decision</label><select name="verification_status"><option>Verified / Correct</option><option>Rejected / Incorrect</option><option>Pending Verification</option></select></div><div class="field"><label>Remarks</label><textarea name="verification_note"></textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save Verification</button></div></form>`)}
async function saveFinanceVerify(e,id){e.preventDefault();try{await api('/api/finance/'+id+'/verify',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast('Finance verification updated');loadView()}catch(x){toast(x.message)}}
async function approvals(c){const a=await api('/api/approvals');c.innerHTML=title('Approvals','Request, review and decision trail for controlled actions','<button class="btn primary" onclick="approvalForm()">+ Request approval</button>')+`<div class="card"><div class="table-wrap"><table class="table"><tr><th>Date</th><th>Type</th><th>Requester</th><th>Business</th><th>Amount</th><th>Step</th><th>Status</th><th>Action</th></tr>${a.map(x=>`<tr><td>${x.created_at}</td><td>${esc(x.type)}</td><td>${esc(x.requester)}</td><td>${esc(x.business_unit||'Company')}</td><td>${money(x.amount)}</td><td>${esc(x.current_step)}</td><td><span class="pill ${x.status==='Approved'?'good':x.status==='Rejected'?'bad':'warn'}">${x.status}</span></td><td>${x.status==='Pending'?`<button class="btn small" onclick="decide(${x.id},'Approved')">Approve</button> <button class="btn small" onclick="decide(${x.id},'Rejected')">Reject</button>`:''}</td></tr>`).join('')}</table></div></div>`}
async function approvalForm(){const u=await api('/api/business-units');modal(`<h2>Approval request</h2><form onsubmit="saveApproval(event)"><div class="grid g2"><div class="field"><label>Type</label><select name="type"><option>Payment</option><option>Purchase</option><option>Discount / Refund</option><option>Supplier / Contract</option><option>Special Expense</option><option>Operational Exception</option></select></div><div class="field"><label>Amount</label><input name="amount" type="number" step="0.01"></div></div><div class="field"><label>Business</label><select name="business_unit_id"><option value="">Company</option>${u.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Reason</label><textarea name="reason" required></textarea></div><div class="field"><label>Attachment</label><input name="attachment" type="file"></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Submit</button></div></form>`)}
async function saveApproval(e){e.preventDefault();try{await api('/api/approvals',{method:'POST',body:new FormData(e.target)});closeModal();toast('Approval submitted');loadView()}catch(x){toast(x.message)}}
async function decide(id,status){try{await api('/api/approvals/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({status})});toast('Approval updated');loadView()}catch(x){toast(x.message)}}
async function tasks(c){const [t,u,b]=await Promise.all([api('/api/tasks'),api('/api/users'),api('/api/business-units')]);c.innerHTML=title('Tasks & Follow-up','Owners, priorities, deadlines, recurring actions and history','<button class="btn primary" onclick="taskForm()">+ New task</button>')+`<div class="card"><div class="table-wrap"><table class="table"><tr><th>Task</th><th>Owner</th><th>Business</th><th>Priority</th><th>Status</th><th>Due</th><th>Action</th></tr>${t.map(x=>`<tr><td><b>${esc(x.title)}</b><div class="muted">${esc(x.expected_result)}</div></td><td>${esc(x.owner)}</td><td>${esc(x.business_unit||'Company')}</td><td><span class="pill ${x.priority==='Critical'?'bad':x.priority==='High'?'warn':'blue'}">${x.priority}</span></td><td>${x.status}</td><td>${x.due_date||'—'}</td><td><button class="btn small" onclick="taskForm(${x.id})">Edit</button> <button class="btn small" onclick="taskStatus(${x.id})">Status</button> <button class="btn small danger" onclick="deleteTask(${x.id})">Delete</button></td></tr>`).join('')}</table></div></div>`;window._users=u;window._units=b}
async function taskForm(id){const [u,b,t]=await Promise.all([api('/api/users'),api('/api/business-units'),id?api('/api/tasks'):Promise.resolve([])]);const x=id?t.find(z=>z.id==id):null;modal(`<h2>${id?'Edit':'New'} task</h2><form onsubmit="saveTask(event,${id||0})"><div class="field"><label>Task</label><input name="title" value="${esc(x?.title||'')}" required></div><div class="grid g2"><div class="field"><label>Owner</label><select name="owner_id">${u.map(z=>`<option value="${z.id}" ${x?.owner_id==z.id?'selected':''}>${esc(z.name)}</option>`).join('')}</select></div><div class="field"><label>Business</label><select name="business_unit_id"><option value="">Company</option>${b.map(z=>`<option value="${z.id}" ${x?.business_unit_id==z.id?'selected':''}>${esc(z.name)}</option>`).join('')}</select></div></div><div class="grid g3"><div class="field"><label>Priority</label><select name="priority">${['Critical','High','Normal','Low'].map(z=>`<option ${x?.priority===z?'selected':''}>${z}</option>`).join('')}</select></div><div class="field"><label>Status</label><select name="status">${['Not Started','In Progress','Waiting','Completed','Cancelled'].map(z=>`<option ${x?.status===z?'selected':''}>${z}</option>`).join('')}</select></div><div class="field"><label>Due</label><input name="due_date" type="date" value="${x?.due_date||''}"></div></div><div class="field"><label>Expected result</label><textarea name="expected_result">${esc(x?.expected_result||'')}</textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">${id?'Update':'Create'}</button></div></form>`)}
async function saveTask(e,id){e.preventDefault();const o=Object.fromEntries(new FormData(e.target));try{await api(id?'/api/tasks/'+id:'/api/tasks',{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});closeModal();toast(id?'Task updated':'Task created');loadView()}catch(x){toast(x.message)}}
async function deleteTask(id){if(!confirm('Delete this task?'))return;try{await api('/api/tasks/'+id,{method:'DELETE'});toast('Task deleted');loadView()}catch(x){toast(x.message)}}
async function taskStatus(id){const s=prompt('Status: Not Started / In Progress / Waiting / Completed / Cancelled','In Progress');if(!s)return;try{await api('/api/tasks/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:s})});loadView()}catch(x){toast(x.message)}}
async function crm(c){const rows=await api('/api/crm');c.innerHTML=title('CRM & Sales Pipeline','Leads, customers, stages, potential value and follow-ups','<button class="btn primary" onclick="crmForm()">+ Lead / Customer</button>')+`<div class="grid g3">${['Lead','Contacted','Qualified','Quotation','Negotiation','Won','Lost'].map(s=>`<div class="card"><div class="section-title"><h3>${s}</h3><span class="pill blue">${rows.filter(x=>x.stage===s).length}</span></div>${rows.filter(x=>x.stage===s).slice(0,6).map(x=>`<div style="padding:8px 0;border-bottom:1px solid var(--line)"><b>${esc(x.company)}</b><div class="muted">${money(x.potential_value)} · ${x.next_followup||'No follow-up'}</div><div style="margin-top:7px"><button class="btn small" onclick="crmEdit(${x.id})">Edit</button> <button class="btn small danger" onclick="deleteCRM(${x.id})">Delete</button></div></div>`).join('')}</div>`).join('')}</div>`}
async function crmForm(){const u=await api('/api/business-units');modal(`<h2>Lead / customer</h2><form onsubmit="saveCRM(event)"><div class="grid g2"><div class="field"><label>Company / Customer</label><input name="company" required></div><div class="field"><label>Contact</label><input name="contact"></div></div><div class="grid g3"><div class="field"><label>Stage</label><select name="stage"><option>Lead</option><option>Contacted</option><option>Qualified</option><option>Quotation</option><option>Negotiation</option><option>Won</option><option>Lost</option></select></div><div class="field"><label>Potential value</label><input name="potential_value" type="number"></div><div class="field"><label>Follow-up</label><input name="next_followup" type="date"></div></div><div class="field"><label>Business</label><select name="business_unit_id"><option value="">Company</option>${u.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Notes</label><textarea name="notes"></textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save</button></div></form>`)}
async function saveCRM(e){e.preventDefault();try{await api('/api/crm',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast('CRM record saved');loadView()}catch(x){toast(x.message)}}
async function reports(c){const rows=await api('/api/reports');c.innerHTML=title('Daily Reports','Completed, pending, blockers, tomorrow priority and status','<button class="btn primary" onclick="reportForm()">+ Submit report</button>')+`<div class="card"><div class="table-wrap"><table class="table"><tr><th>Date</th><th>User</th><th>Status</th><th>Completed</th><th>Pending</th><th>Blockers</th><th>Tomorrow</th></tr>${rows.map(x=>`<tr><td>${x.report_date}</td><td>${esc(x.user_name)}</td><td><span class="pill ${x.status==='Green'?'good':x.status==='Yellow'?'warn':'bad'}">${x.status}</span></td><td>${esc(x.completed)}</td><td>${esc(x.pending)}</td><td>${esc(x.blockers)}</td><td>${esc(x.tomorrow_priority)}</td></tr>`).join('')}</table></div></div>`}
function reportForm(){modal(`<h2>Daily report</h2><form onsubmit="saveReport(event)"><div class="field"><label>Date</label><input name="report_date" type="date" value="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label>Completed</label><textarea name="completed"></textarea></div><div class="field"><label>Pending</label><textarea name="pending"></textarea></div><div class="field"><label>Problems / blockers</label><textarea name="blockers"></textarea></div><div class="field"><label>Tomorrow priority</label><textarea name="tomorrow_priority"></textarea></div><div class="grid g2"><div class="field"><label>Need help</label><input name="need_help"></div><div class="field"><label>Status</label><select name="status"><option>Green</option><option>Yellow</option><option>Red</option></select></div></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Submit</button></div></form>`)}
async function saveReport(e){e.preventDefault();try{await api('/api/reports',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast('Daily report saved');loadView()}catch(x){toast(x.message)}}
async function kpis(c){const rows=await api('/api/kpis');c.innerHTML=title('KPIs & Performance','Targets, actuals, owners and business-unit performance','<button class="btn primary" onclick="kpiForm()">+ KPI</button>')+`<div class="grid g3">${rows.map(x=>{const pct=x.target?Math.min(100,Math.round(x.actual/x.target*100)):0;return `<div class="card"><div class="section-title"><h3>${esc(x.name)}</h3><span class="pill ${pct>=100?'good':pct>=70?'blue':'warn'}">${pct}%</span></div><div class="muted">${esc(x.user_name||x.business_unit||'Company')} · ${x.period}</div><div style="margin:14px 0" class="kpi-meter"><i style="width:${pct}%"></i></div><b>${money(x.actual)}</b> / ${money(x.target)}<div style="margin-top:10px"><button class="btn small" onclick="kpiEdit(${x.id})">Edit</button> <button class="btn small danger" onclick="deleteKPI(${x.id})">Delete</button></div></div>`}).join('')}</div>`}
async function kpiForm(){const [u,b]=await Promise.all([api('/api/users'),api('/api/business-units')]);modal(`<h2>Add KPI</h2><form onsubmit="saveKPI(event)"><div class="field"><label>Name</label><input name="name" required></div><div class="grid g2"><div class="field"><label>Target</label><input name="target" type="number"></div><div class="field"><label>Actual</label><input name="actual" type="number"></div></div><div class="grid g2"><div class="field"><label>User</label><select name="user_id"><option value="">Company / Unit</option>${u.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Business</label><select name="business_unit_id"><option value="">Company</option>${b.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save</button></div></form>`)}
async function saveKPI(e){e.preventDefault();try{await api('/api/kpis',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast('KPI saved');loadView()}catch(x){toast(x.message)}}
async function documents(c){const rows=await api('/api/documents');c.innerHTML=title('Documents & SOP Center','SOPs, templates, policies, contracts and business files','<button class="btn primary" onclick="docForm()">+ Upload</button>')+`<div class="card"><div class="table-wrap"><table class="table"><tr><th>Title</th><th>Category</th><th>Version</th><th>Business</th><th>Uploaded by</th><th>Date</th><th>File</th><th>Actions</th></tr>${rows.map(x=>`<tr><td>${esc(x.title)}</td><td>${esc(x.category)}</td><td>${esc(x.version)}</td><td>${esc(x.business_unit||'Company')}</td><td>${esc(x.uploaded_by_name)}</td><td>${x.created_at}</td><td><a href="/uploads/${esc(x.file_path)}" target="_blank">Open</a></td><td><button class="btn small danger" onclick="deleteDoc(${x.id})">Delete</button></td></tr>`).join('')}</table></div></div>`}
async function docForm(){const u=await api('/api/business-units');modal(`<h2>Upload document</h2><form onsubmit="saveDoc(event)"><div class="field"><label>Title</label><input name="title"></div><div class="grid g3"><div class="field"><label>Category</label><select name="category"><option>SOP</option><option>Template</option><option>Policy</option><option>Contract</option><option>Business File</option><option>Product</option></select></div><div class="field"><label>Version</label><input name="version" value="1.0"></div><div class="field"><label>Business</label><select name="business_unit_id"><option value="">Company</option>${u.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div></div><div class="field"><label>File</label><input name="file" type="file" required></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Upload</button></div></form>`)}
async function saveDoc(e){e.preventDefault();try{await api('/api/documents',{method:'POST',body:new FormData(e.target)});closeModal();toast('Document uploaded');loadView()}catch(x){toast(x.message)}}
async function meetings(c){const rows=await api('/api/meetings');c.innerHTML=title('Weekly Management Meetings','Review agenda, actions, owners and follow-through','<button class="btn primary" onclick="meetingForm()">+ Meeting</button>')+`<div class="grid g2">${rows.map(x=>`<div class="card"><div class="section-title"><h3>${esc(x.title)}</h3><span class="pill blue">${x.meeting_date}</span></div><p>${esc(x.summary)}</p><button class="btn small" onclick="meetingForm(${x.id})">Edit</button> <button class="btn small" onclick="meetingAction(${x.id})">+ Action</button> <button class="btn small danger" onclick="deleteMeeting(${x.id})">Delete</button></div>`).join('')}</div>`}
async function meetingForm(id){const rows=id?await api('/api/meetings'):[];const x=id?rows.find(z=>z.id==id):null;modal(`<h2>${id?'Edit':'Weekly management meeting'}</h2><form onsubmit="saveMeeting(event,${id||0})"><div class="field"><label>Date</label><input name="meeting_date" type="date" value="${x?.meeting_date||new Date().toISOString().slice(0,10)}"></div><div class="field"><label>Title</label><input name="title" value="${esc(x?.title||'Weekly Management Meeting')}"></div><div class="field"><label>Summary</label><textarea name="summary">${esc(x?.summary||'')}</textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">${id?'Update':'Create'}</button></div></form>`)}
async function saveMeeting(e,id){e.preventDefault();const o=Object.fromEntries(new FormData(e.target));try{await api(id?'/api/meetings/'+id:'/api/meetings',{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});closeModal();toast(id?'Meeting updated':'Meeting created');loadView()}catch(x){toast(x.message)}}
async function deleteMeeting(id){if(!confirm('Delete this meeting and its actions?'))return;try{await api('/api/meetings/'+id,{method:'DELETE'});toast('Meeting deleted');loadView()}catch(x){toast(x.message)}}
async function meetingAction(id){const u=await api('/api/users');modal(`<h2>Meeting action</h2><form onsubmit="saveMeetingAction(event)"><input type="hidden" name="meeting_id" value="${id}"><div class="field"><label>Action</label><input name="title" required></div><div class="grid g2"><div class="field"><label>Owner</label><select name="owner_id">${u.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Due</label><input name="due_date" type="date"></div></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save</button></div></form>`)}
async function saveMeetingAction(e){e.preventDefault();try{await api('/api/meeting-actions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast('Meeting action assigned')}catch(x){toast(x.message)}}
async function users(c){const rows=await api('/api/users');c.innerHTML=title('People & Access','Role-based dashboards and business-unit assignment','<button class="btn primary" onclick="userForm()">+ User</button>')+`<div class="card"><div class="table-wrap"><table class="table"><tr><th>Name</th><th>Email</th><th>Role</th><th>Business</th><th>Status</th><th>Created</th><th>Actions</th></tr>${rows.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.email)}</td><td><span class="pill blue">${esc(x.role)}</span></td><td>${esc(x.business_unit||'All')}</td><td>${x.active?'Active':'Inactive'}</td><td>${x.created_at}</td><td>${me.role==='CEO / Owner'||me.role==='Operations Manager'?`<button class="btn small" onclick="userEdit(${x.id})">Edit</button> ${x.active?`<button class="btn small danger" onclick="userDeactivate(${x.id})">Deactivate</button>`:`<button class="btn small" onclick="userActivate(${x.id})">Activate</button>`} ${me.role==='CEO / Owner'&&x.id!==me.id?`<button class="btn small danger" onclick="userPermanentDelete(${x.id})">Delete Profile</button>`:''}`:''}</td></tr>`).join('')}</table></div></div>`}
async function userForm(){const b=await api('/api/business-units');modal(`<h2>Add user</h2><form onsubmit="saveUser(event)"><div class="grid g2"><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Email</label><input name="email" type="email" required></div></div><div class="grid g2"><div class="field"><label>Temporary password</label><input name="password" value="ChangeMe@123"></div><div class="field"><label>Role</label><select name="role">${roles.map(x=>`<option>${x}</option>`).join('')}</select></div></div><div class="field"><label>Business unit</label><select name="business_unit_id"><option value="">All / Company</option>${b.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Create</button></div></form>`)}
async function saveUser(e){e.preventDefault();try{await api('/api/users',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast('User created');loadView()}catch(x){toast(x.message)}}
async function notificationsView(c){try{const n=await api('/api/notifications');c.innerHTML=title('Notifications & Alerts','All alerts, reminders and system notifications')+`<div class="card">${n.length?n.map(x=>`<div class="notif" style="margin-bottom:10px"><span class="pill ${x.level==='critical'?'bad':x.level==='warning'?'warn':'blue'}">${esc(x.level)}</span> <b>${esc(x.title)}</b><div class="muted">${esc(x.message)}</div><div class="muted">${x.created_at}</div>${!x.read_at?`<button class="btn small" onclick="readNotif(${x.id});loadView()">Mark read</button>`:''}</div>`).join(''):'<div class="empty">No notifications or alerts.</div>'}</div>`}catch(e){c.innerHTML=title('Notifications & Alerts','Unable to load notifications')+`<div class="card"><b>${esc(e.message)}</b><button class="btn primary" onclick="loadView()">Retry</button></div>`}}
async function profileView(c){try{const u=(await api('/api/me')).user;c.innerHTML=title('My Profile','Manage your account information and password')+`<div class="grid g2"><div class="card"><h3>Profile information</h3><form onsubmit="saveProfile(event)"><div class="field"><label>Name</label><input name="name" value="${esc(u.name)}" required></div><div class="field"><label>Email</label><input name="email" type="email" value="${esc(u.email)}" required></div><div class="field"><label>Role</label><input value="${esc(u.role)}" disabled></div><div class="actions"><button class="btn primary">Save profile</button></div></form></div><div class="card"><h3>Change password</h3><form onsubmit="changePassword(event)"><div class="field"><label>Current password</label><input name="current_password" type="password" required></div><div class="field"><label>New password</label><input name="new_password" type="password" minlength="8" required></div><div class="field"><label>Confirm new password</label><input name="confirm_password" type="password" minlength="8" required></div><div class="actions"><button class="btn primary">Change password</button></div></form></div></div>`}catch(e){c.innerHTML=title('My Profile','Unable to load profile')+`<div class="card"><b>${esc(e.message)}</b></div>`}}
async function saveProfile(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{const r=await api('/api/me/profile',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});me=r.user;localStorage.setItem('bo_user',JSON.stringify(me));toast('Profile updated');render()}catch(x){toast(x.message)}}
async function changePassword(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(d.new_password!==d.confirm_password)return toast('New passwords do not match');try{await api('/api/me/password',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});e.target.reset();toast('Password changed successfully')}catch(x){toast(x.message)}}
async function auditView(c){const rows=await api('/api/audit');c.innerHTML=title('Audit History','Traceable activity across users, finance, inventory, sales, approvals and documents')+`<div class="card"><div class="table-wrap"><table class="table"><tr><th>Date</th><th>User</th><th>Entity</th><th>Action</th><th>Details</th></tr>${rows.map(x=>`<tr><td>${x.created_at}</td><td>${esc(x.user_name||'System')}</td><td>${esc(x.entity)} #${x.entity_id||''}</td><td>${esc(x.action)}</td><td>${esc(x.details)}</td></tr>`).join('')}</table></div></div>`}
async function restaurant(c){const [p,t,o]=await Promise.all([api('/api/products'),api('/api/restaurant/tables'),api('/api/restaurant/orders')]);const menu=p.filter(x=>x.business_unit==='MIMI Resturant');c.innerHTML=title('MIMI Resturant · POS','Dine-in, takeaway, delivery, kitchen flow, inventory and daily closing','<button class="btn primary" onclick="restaurantPOS()">Open POS</button>')+`<div class="grid g3"><div class="card"><div class="section-title"><h3>Tables</h3><button class="btn small" onclick="tableForm()">+ Table</button></div><div class="room">${t.map(x=>`<div class="table-tile ${x.status==='Busy'?'busy':''}"><b>${esc(x.name)}</b><div class="muted">${x.capacity} seats</div><div style="margin-top:8px"><span class="pill ${x.status==='Available'?'good':'warn'}">${x.status}</span> <button class="btn small" onclick="tableForm(${x.id})">Edit</button> <button class="btn small danger" onclick="deleteTable(${x.id})">Delete</button></div></div>`).join('')}</div></div><div class="card"><h3>Menu</h3><div style="display:grid;gap:8px;margin-top:10px">${menu.map(x=>`<div style="display:flex;justify-content:space-between"><span>${esc(x.name)}</span><b>${money(x.selling_price)}</b></div>`).join('')}</div></div><div class="card"><h3>Recent orders</h3><div style="display:grid;gap:8px;margin-top:10px">${o.slice(0,8).map(x=>`<div style="display:flex;justify-content:space-between"><span>${esc(x.order_no)}</span><span class="pill ${x.status==='Closed'?'good':'warn'}">${x.status}</span></div>`).join('')}</div></div></div><div class="card" style="margin-top:16px"><div class="section-title"><h3>Restaurant controls</h3><div><button class="btn small" onclick="wasteForm()">Waste</button> <button class="btn small" onclick="closingForm()">Daily closing</button></div></div><p class="muted">MIMI orders are connected to the central sales, inventory, finance and profit reporting layers.</p></div>`}

async function manageRestaurantTables(){const t=await api('/api/restaurant/tables');modal(`<h2>MIMI · Restaurant Tables</h2><div class="actions" style="justify-content:flex-start"><button class="btn primary" onclick="tableForm();">+ Add Table</button></div><div class="table-wrap" style="margin-top:12px"><table class="table"><tr><th>Table</th><th>Capacity</th><th>Status</th><th>Actions</th></tr>${t.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.capacity}</td><td><span class="pill ${x.status==='Available'?'good':x.status==='Busy'?'bad':'warn'}">${esc(x.status)}</span></td><td><button class="btn small" onclick="tableForm(${x.id})">Edit</button> <button class="btn small danger" onclick="deleteRestaurantTable(${x.id})">Delete Table</button></td></tr>`).join('')}</table></div>`)}
async function deleteRestaurantTable(id){if(!confirm('Delete this table? This is only allowed when the table has no open order.'))return;try{await api('/api/restaurant/tables/'+id,{method:'DELETE'});toast('Table deleted');manageRestaurantTables();loadView()}catch(x){toast(x.message)}}
async function excavatorSuppliers(c){
  const rows=await api('/api/excavator/suppliers');
  const totalMachines=rows.reduce((n,s)=>n+Number(s.available_machine_count||0),0);
  const body=`<div class="grid g4"><div class="card stat"><div class="label">Suppliers</div><div class="value">${rows.length}</div></div><div class="card stat"><div class="label">Available Machines</div><div class="value">${totalMachines}</div></div><div class="card stat"><div class="label">Suppliers with Machines</div><div class="value">${rows.filter(x=>Number(x.available_machine_count||0)>0).length}</div></div><div class="card stat"><div class="label">Workspace</div><div class="value" style="font-size:20px">Excavator</div></div></div><div class="card" style="margin-top:16px"><div class="section-title"><div><h2 style="margin:0">Supplier Management</h2><div class="muted">Manage supplier profiles, available machines and requirements. Existing supplier functionality is preserved.</div></div><div style="display:flex;gap:8px;align-items:center"><input id="excavatorSupplierSearch" class="search" placeholder="Search supplier, location, contact..." oninput="filterExcavatorSupplierRows()"><button class="btn primary" onclick="excavatorSupplierForm()">+ Add Supplier</button></div></div><div class="table-wrap"><table class="table" id="excavatorSupplierTable"><tr><th>Supplier</th><th>Location</th><th>Contact</th><th>Available Machines</th><th>Actions</th></tr>${rows.map(s=>`<tr data-search="${esc((s.name+' '+s.location+' '+(s.contact_person||'')+' '+(s.phone||'')+' '+(s.email||'')).toLowerCase())}"><td><b>${esc(s.name)}</b><div class="muted">${esc(s.address||'')}</div></td><td>${esc(s.location)}</td><td>${esc(s.contact_person||'—')}<div class="muted">${esc(s.phone||s.email||'')}</div></td><td><span class="pill ${Number(s.available_machine_count||0)>0?'good':'blue'}">${Number(s.available_machine_count||0)}</span></td><td><button class="btn small primary" onclick="excavatorSupplierMachines(${s.id})">Machines</button><button class="btn small" onclick="excavatorSupplierRequirements(${s.id})">Requirements</button><button class="btn small" onclick="excavatorSupplierForm(${s.id})">Edit</button><button class="btn small danger" onclick="deleteExcavatorSupplier(${s.id})">Delete</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No suppliers yet.</td></tr>'}</table></div></div>`;
  if(c){c.innerHTML=title('Excavator Suppliers','Supplier workspace · profiles, available machines and requirements', '')+body;}else{modal(`<h2>Excavator Suppliers</h2>${body}`);}
}
function filterExcavatorSupplierRows(){const q=(document.getElementById('excavatorSupplierSearch')?.value||'').toLowerCase();document.querySelectorAll('#excavatorSupplierTable tr[data-search]').forEach(r=>r.style.display=r.dataset.search.includes(q)?'':'none')}
async function deleteExcavatorSupplier(id){
  if(!confirm('Delete this supplier? Supplier-listed machines and requirements will be removed, while existing machine/deal history will be preserved.'))return;
  try{await api('/api/excavator/suppliers/'+id,{method:'DELETE'});toast('Supplier deleted');excavatorSuppliers()}catch(x){toast(x.message)}
}
async function excavatorSupplierForm(id){const s=id?(await api('/api/excavator/suppliers')).find(x=>x.id==id):null;modal(`<h2>${id?'Edit':'Add'} Supplier</h2><form onsubmit="saveExcavatorSupplier(event,${id||0})"><div class="grid g2"><div class="field"><label>Supplier Name</label><input name="name" value="${esc(s?.name||'')}" required></div><div class="field"><label>Location</label><input name="location" value="${esc(s?.location||'')}" required></div></div><div class="grid g2"><div class="field"><label>Contact Person</label><input name="contact_person" value="${esc(s?.contact_person||'')}"></div><div class="field"><label>Phone</label><input name="phone" value="${esc(s?.phone||'')}"></div></div><div class="grid g2"><div class="field"><label>Email</label><input name="email" value="${esc(s?.email||'')}"></div><div class="field"><label>Address</label><input name="address" value="${esc(s?.address||'')}"></div></div><div class="field"><label>Notes</label><textarea name="notes">${esc(s?.notes||'')}</textarea></div><div class="actions"><button type="button" class="btn" onclick="excavatorSuppliers()">Cancel</button><button class="btn primary">Save Supplier</button></div></form>`)}
async function saveExcavatorSupplier(e,id){e.preventDefault();try{const o=Object.fromEntries(new FormData(e.target));await api(id?'/api/excavator/suppliers/'+id:'/api/excavator/suppliers',{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});toast('Supplier saved');excavatorSuppliers()}catch(x){toast(x.message)}}
async function excavatorSupplierMachines(id){
  const d=await api('/api/excavator/suppliers/'+id+'/machines');
  const listed=d.listed||[], purchased=d.purchased||[];
  const machineRows=listed.map(a=>`<div class="card" style="margin:10px 0"><div class="section-title"><div><h3 style="margin:0">${esc(a.machine_name||'Machine')}</h3><div class="muted">${esc(a.machine_type||'')} · ${esc(a.make||'')} ${esc(a.model||'')} · ${a.year||'Year n/a'} · ${esc(a.condition_status||'')}</div></div><span class="pill good">${esc(a.status||'Available')}</span></div><div class="grid g3" style="margin-top:10px"><div><small>Serial / Chassis</small><div>${esc(a.serial_no||'—')}</div></div><div><small>Asking Price</small><div><b>₩ ${money(a.asking_price)}</b></div></div><div><small>Location</small><div>${esc(a.location||'—')}</div></div></div><div style="margin-top:8px"><small>Notes</small><div>${esc(a.notes||'—')}</div></div><div class="actions" style="margin-top:10px"><button class="btn small" onclick="excavatorSupplierMachineForm(${id},${a.id})">Edit</button><button class="btn small danger" onclick="deleteExcavatorSupplierMachine(${id},${a.id})">Delete</button></div></div>`).join('');
  modal(`<h2>${esc(d.supplier?.name||'Supplier')} · Machines</h2>
    <div class="section-title"><div><h3>Supplier's available machines</h3><div class="muted">Complete details are shown below. Sold or purchased machines automatically leave this list.</div></div><button class="btn primary" onclick="excavatorSupplierMachineForm(${id})">+ Add Machine</button></div>
    ${machineRows||'<div class="empty">No supplier-listed machines.</div>'}
    <div class="section-title" style="margin-top:18px"><h3>Machines purchased from this supplier</h3></div>
    ${purchased.map(a=>`<div class="card" style="margin:10px 0"><div class="section-title"><div><h3 style="margin:0">${esc(a.machine_name||a.make+' '+a.model)}</h3><div class="muted">Deal ${esc(machine.asset_no)} · ${esc(a.make||'')} ${esc(a.model||'')} · ${esc(a.serial_no||'No serial')}</div></div><span class="pill blue">Purchased</span></div><div class="grid g3" style="margin-top:10px"><div><small>Purchase Date</small><div>${esc(a.purchase_date||'—')}</div></div><div><small>Purchase Price</small><div><b>₩ ${money(a.purchase_price)}</b></div></div><div><small>Status</small><div>${esc(a.lifecycle_stage||a.status||'—')}</div></div></div></div>`).join('')||'<div class="empty">No company purchases from this supplier yet.</div>'}
    <div class="actions"><button class="btn" onclick="excavatorSuppliers()">Back</button></div>`);
}
async function deleteExcavatorSupplierMachine(supplierId,machineId){
  if(!confirm('Delete this supplier-listed machine?'))return;
  try{await api('/api/excavator/suppliers/'+supplierId+'/machines/'+machineId,{method:'DELETE'});toast('Machine deleted');excavatorSupplierMachines(supplierId)}catch(x){toast(x.message)}
}
