function countryFlag(country){const m={'Pakistan':'🇵🇰','South Korea':'🇰🇷','Korea':'🇰🇷','United Arab Emirates':'🇦🇪','UAE':'🇦🇪','Saudi Arabia':'🇸🇦','China':'🇨🇳','Japan':'🇯🇵','United States':'🇺🇸','USA':'🇺🇸','United Kingdom':'🇬🇧','UK':'🇬🇧','Turkey':'🇹🇷','Germany':'🇩🇪','France':'🇫🇷'};return m[String(country||'').trim()]||'🌐'}
async function excavatorBuyerForm(id){const rows=await api('/api/excavator/buyers');const x=id?rows.find(r=>r.id==id):null;modal(`<h2>${id?'Edit':'Add'} Buyer</h2><form onsubmit="saveExcavatorBuyer(event,${id||0})"><div class="grid g2"><div class="field"><label>Buyer / Company Name</label><input name="name" value="${esc(x?.name||'')}" required></div><div class="field"><label>Country</label><input name="country" value="${esc(x?.country||'Pakistan')}" required></div><div class="field"><label>Buyer Type *</label><select name="buyer_type" required><option value="International" ${x?.buyer_type!=='Local'?'selected':''}>International</option><option value="Local" ${x?.buyer_type==='Local'?'selected':''}>Local</option></select></div><div class="field"><label>Location / City</label><input name="location" value="${esc(x?.location||'')}"></div><div class="field"><label>Contact Person</label><input name="contact_person" value="${esc(x?.contact_person||'')}"></div><div class="field"><label>Phone</label><input name="phone" value="${esc(x?.phone||'')}"></div><div class="field"><label>WhatsApp</label><input name="whatsapp" value="${esc(x?.whatsapp||'')}"></div><div class="field"><label>Email</label><input name="email" type="email" value="${esc(x?.email||'')}"></div><div class="field"><label>Payment Terms</label><input name="payment_terms" value="${esc(x?.payment_terms||'')}" placeholder="e.g. Advance before purchase"></div></div><div class="field"><label>Address</label><textarea name="address">${esc(x?.address||'')}</textarea></div><div class="field"><label>Notes</label><textarea name="notes">${esc(x?.notes||'')}</textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save Buyer</button></div></form>`)}
