async function excavatorBuyerDetail(id){const d=await api('/api/excavator/buyers/'+id);const b=d.buyer;const resale=d.resale_profit_eligible?`<div class="card" style="margin-bottom:12px"><div class="section-title"><h3>Pakistan Resale Profit Share</h3><button class="btn small primary" onclick="closeModal();excavatorBuyerResaleForm(${id})">+ Add Resale Record</button></div><div class="muted" style="margin-bottom:8px">Manual recording only. Resale figures are in PKR and are not automatically calculated.</div>${(d.resale_shares||[]).map(r=>`<div class="card" style="margin-bottom:8px"><div class="section-title"><b>${esc(r.asset_no)} · ${esc(r.machine_name||'Machine')}</b><span class="pill ${r.received?'good':'warn'}">${r.received?'Received':'Outstanding'}</span></div><div class="grid g4"><div><small>Resale Price</small><b>PKR ${money(r.resale_price_pkr)}</b></div><div><small>Manual Resale Profit</small><b>PKR ${money(r.resale_profit_pkr)}</b></div><div><small>Our Share</small><b>${money(r.share_percent)}% · PKR ${money(r.our_share_pkr)}</b></div><div><small>Received / Outstanding</small><b>PKR ${money(r.amount_received_pkr)} / ${money(r.outstanding_pkr)}</b></div></div><div class="actions"><button class="btn small" onclick="editExcavatorBuyerResale(${id},${r.id})">Edit</button><button class="btn small danger" onclick="deleteExcavatorBuyerResale(${id},${r.id})">Delete</button>${r.receipt_file?`<a class="btn small" target="_blank" href="/uploads/${esc(r.receipt_file)}">Receipt</a>`:''}</div></div>`).join('')||'<div class="muted">No resale-profit records yet.</div>'}</div>`:'';modal(`<div class="section-title"><div><div class="muted">Buyer</div><h2 style="margin:2px 0">${esc(b.name)}</h2><div><span style="font-size:20px">${countryFlag(b.country)}</span> ${esc(b.country||'')} · <span class="pill ${b.buyer_type==='Local'?'blue':'good'}">${b.buyer_type==='Local'?'Local':'International'}</span> · ${esc(b.location||'')}</div></div><button class="btn" onclick="closeModal()">✕</button></div><div class="grid g4" style="margin:14px 0"><div class="card stat"><small>Total Payments</small><b>₩ ${money(d.balance.total_paid_krw)}</b></div><div class="card stat"><small>Allocated</small><b>₩ ${money(d.balance.allocated_krw)}</b></div><div class="card stat"><small>Available Advance</small><b class="good">₩ ${money(d.balance.available_advance_krw)}</b></div><div class="card stat"><small>Machines</small><b>${d.machines.length}</b></div></div><div class="card" style="margin-bottom:12px"><div class="section-title"><h3>Buyer Details</h3><button class="btn small" onclick="closeModal();excavatorBuyerForm(${id})">Edit</button></div><div class="grid g3"><div><small>Type</small><b>${esc(b.buyer_type||'International')}</b></div><div><small>Country</small><b>${countryFlag(b.country)} ${esc(b.country||'—')}</b></div><div><small>Contact</small><b>${esc(b.contact_person||'—')}</b></div><div><small>Phone</small><b>${esc(b.phone||'—')}</b></div><div><small>WhatsApp</small><b>${esc(b.whatsapp||'—')}</b></div><div><small>Email</small><b>${esc(b.email||'—')}</b></div><div><small>Payment Terms</small><b>${esc(b.payment_terms||'—')}</b></div><div><small>Location</small><b>${esc(b.location||'—')}</b></div><div><small>Address</small><b>${esc(b.address||'—')}</b></div></div></div><div class="card" style="margin-bottom:12px"><div class="section-title"><h3>Payments & Advance Allocation</h3><button class="btn primary small" onclick="closeModal();excavatorBuyerPaymentForm(${id})">+ Add Payment</button></div><div class="table-wrap"><table class="table"><tr><th>Date</th><th>Type</th><th>Original</th><th>Rate</th><th>KRW</th><th>Available</th><th>Reference</th><th>Receipt</th><th></th></tr>${d.payments.map(p=>`<tr><td>${esc(p.payment_date)}</td><td>${esc(p.payment_type)}</td><td>${money(p.original_amount)} ${esc(p.currency)}</td><td>${money(p.fx_rate)}</td><td>₩ ${money(p.krw_amount)}</td><td>₩ ${money(p.available_krw)}</td><td>${esc(p.reference)}</td><td>${p.receipt_file?`<a class="btn small" target="_blank" href="/uploads/${esc(p.receipt_file)}">Receipt</a>`:'—'}</td><td><button class="btn small danger" onclick="deleteExcavatorBuyerPayment(${id},${p.id})">Delete</button></td></tr>`).join('')||'<tr><td colspan="9" class="empty">No payments yet.</td></tr>'}</table></div>${d.allocations?.length?`<div class="table-wrap" style="margin-top:10px"><table class="table"><tr><th>Allocation Date</th><th>Machine</th><th>Amount (KRW)</th><th>Payment Ref</th></tr>${d.allocations.map(a=>`<tr><td>${esc(a.allocation_date)}</td><td>${esc(a.asset_no)} · ${esc(a.machine_name||'Machine')}</td><td>₩ ${money(a.amount_krw)}</td><td>${esc(a.reference||'')}</td></tr>`).join('')}</table></div>`:''}</div><div class="card" style="margin-bottom:12px"><div class="section-title"><h3>Machines Sold</h3></div>${d.machines.map(m=>`<div class="row"><span><b>${esc(m.asset_no)}</b> · ${esc(m.machine_name||m.make+' '+m.model)}</span><b>₩ ${money(m.selling_price)} · ${esc(m.lifecycle_stage||'')}</b></div>`).join('')||'<div class="muted">No machines linked.</div>'}</div>${resale}<div class="card"><div class="section-title"><h3>Buyer Requirements</h3><button class="btn small primary" onclick="closeModal();excavatorBuyerRequirementForm(${id})">+ Add Requirement</button></div>${d.requirements.map(r=>`<div class="row"><span>${esc(r.requirement||r.machine_type||'Machine')}<small class="muted"> · ${esc(r.make||'')} ${esc(r.model||'')}</small></span><button class="btn small danger" onclick="deleteExcavatorBuyerRequirement(${id},${r.id})">Delete</button></div>`).join('')||'<div class="muted">No requirements.</div>'}</div><div class="card"><div class="section-title"><h3>Buyer Documents</h3></div>${(d.documents||[]).map(x=>`<div class="row"><span><b>${esc(x.title||'Document')}</b><small class="muted"> · ${esc(x.original_name||'')} · ${esc(x.created_at||'')}</small></span><a class="btn small" target="_blank" href="${esc(x.file_path||'')}">Open</a></div>`).join('')||'<div class="muted">No buyer documents yet. Payment and resale receipts will appear here automatically.</div>'}</div>`)}
async function excavatorBuyerPaymentForm(id){const assets=await api('/api/excavator/assets');const today=new Date().toISOString().slice(0,10);modal(`<h2>Add Buyer Payment</h2><p class="muted">Accounting is stored in KRW. Select the currency actually received and enter the exchange rate used on that payment date. The original amount, currency and historical rate are preserved.</p><form onsubmit="saveExcavatorBuyerPayment(event,${id})" enctype="multipart/form-data"><div class="grid g3"><div class="field"><label>Payment Type</label><select name="payment_type"><option>Advance</option><option>Machine Allocation</option><option>Other</option></select></div><div class="field"><label>Amount Paid *</label><input name="original_amount" type="number" min="0.01" step="0.01" required></div><div class="field"><label>Payment Currency *</label><select name="currency" id="buyerPayCurrency" onchange="buyerCurrencyChanged()" required><option value="KRW">KRW</option><option value="USD">USD</option><option value="PKR">PKR</option></select></div></div><div class="grid g3"><div class="field"><label>Conversion Rate to KRW *</label><input id="buyerFxRate" name="fx_rate" type="number" min="0.000001" step="0.000001" value="1" required><small class="muted">KRW value of 1 unit of the selected payment currency.</small></div><div class="field"><label>Payment Date *</label><input name="payment_date" type="date" value="${today}" required></div><div class="field"><label>Reference *</label><input name="reference" required></div></div><div id="buyerKrwPreview" class="workspace-banner"><b>KRW accounting value: ₩ 0</b><span>Enter amount and rate to preview the stored KRW value.</span></div><div class="grid g2"><div class="field"><label>Method</label><select name="method"><option>Bank</option><option>Cash</option><option>Card</option><option>Other</option></select></div><div class="field"><label>Allocate to Machine (optional)</label><select name="asset_id"><option value="">Unallocated Buyer Advance</option>${assets.map(a=>`<option value="${a.id}">${esc(a.asset_no)} · ${esc(a.machine_name||a.make+' '+a.model)}</option>`).join('')}</select></div></div><div class="field"><label>Payment Receipt</label><input name="receipt" type="file" accept="application/pdf,image/*"></div><div class="field"><label>Notes</label><textarea name="notes"></textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal();excavatorBuyerDetail(${id})">Cancel</button><button class="btn primary">Save Payment</button></div></form>`);const f=document.querySelector('#buyerPayCurrency')?.closest('form');if(f){f.querySelector('[name=original_amount]')?.addEventListener('input',buyerPaymentPreview);f.querySelector('[name=fx_rate]')?.addEventListener('input',buyerPaymentPreview);buyerCurrencyChanged();buyerPaymentPreview();}}
function buyerCurrencyChanged(){const c=document.getElementById('buyerPayCurrency'),r=document.getElementById('buyerFxRate');if(!c||!r)return;const isKrw=c.value==='KRW';r.value=isKrw?'1':(r.value==='1'?'':r.value);r.disabled=isKrw;r.required=!isKrw;buyerPaymentPreview();}
function buyerPaymentPreview(){const f=document.getElementById('buyerPayCurrency')?.closest('form'),p=document.getElementById('buyerKrwPreview');if(!f||!p)return;const amount=Number(f.querySelector('[name=original_amount]')?.value||0),rate=Number(f.querySelector('[name=fx_rate]')?.value||0),cur=f.querySelector('[name=currency]')?.value||'KRW',krw=cur==='KRW'?amount:amount*rate;p.innerHTML=`<b>KRW accounting value: ₩ ${money(krw)}</b><span>${cur==='KRW'?'KRW payment — fixed rate 1.':`Stored using ${money(rate)} KRW per 1 ${esc(cur)}.`}</span>`;}
async function saveExcavatorBuyerPayment(e,id){e.preventDefault();const form=e.target;if(!form.reportValidity())return;try{const fd=new FormData(form);const cur=String(fd.get('currency')||'KRW');if(cur==='KRW')fd.set('fx_rate','1');const r=await fetch('/api/excavator/buyers/'+id+'/payments',{method:'POST',headers:{Authorization:'Bearer '+token,'X-Business-Unit-ID':selectedUnitId||''},body:fd});const j=await r.json();if(!r.ok)throw new Error(j.error||'Payment could not be saved');closeModal();toast('Buyer payment saved in KRW');excavatorBuyerDetail(id)}catch(x){toast(x.message)}}
async function deleteExcavatorBuyerPayment(id,pid){if(!confirm('Delete this buyer payment?'))return;try{await api('/api/excavator/buyers/'+id+'/payments/'+pid,{method:'DELETE'});toast('Payment deleted');excavatorBuyerDetail(id)}catch(x){toast(x.message)}}

