function selectBuySupplier(value){
  const suppliers=[...document.querySelectorAll('#buySupplierList option')];
  const exact=suppliers.find(o=>o.value.toLowerCase()===String(value||'').toLowerCase());
  const id=document.getElementById('buySupplierId'), opt=document.getElementById('buySupplierOption'), box=document.getElementById('newSupplierFields');
  if(!id||!opt||!box)return;
  if(String(value||'').trim()==='Other / New Supplier'){
    id.value=''; opt.value='Other / New Supplier'; box.style.display='block';
  }else if(exact && exact.dataset.id){
    id.value=exact.dataset.id; opt.value=''; box.style.display='none';
  }else{
    id.value=''; opt.value=''; box.style.display='none';
  }
}

async function saveSimpleExcavatorMachine(e){
  e.preventDefault();
  const form=e.target,btn=form.querySelector('button[type="submit"]');
  if(btn){btn.disabled=true;btn.textContent='Saving…'}
  try{
    const o=Object.fromEntries(new FormData(form));
    if(!o.asset_no||!o.machine_name||!o.make||!o.model||!o.purchase_date||Number(o.purchase_price)<=0) throw new Error('Please complete Deal No., Machine Name, Make, Model, Purchase Date and Purchase Price.');
    const result=await api('/api/excavator/assets',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});
    closeModal();
    if(result.new_supplier) toast('Machine saved · New supplier added to the supplier list for future use');
    else if(result.requirement_matches) toast(`Machine saved · ${result.requirement_matches} supplier requirement match(es) found`);
    else toast('Machine saved successfully');
    loadView().catch(err=>console.error('Excavator refresh:',err));
  }catch(x){
    if(btn){btn.disabled=false;btn.textContent='Save Machine'}
    console.error('Excavator save:',x);
    toast(x.message||'Machine could not be saved');
  }
}
async function excavatorOpenMachine(id){
  const [assets,tx,docs,hist,payments]=await Promise.all([api('/api/excavator/assets'),api('/api/excavator/assets/'+id+'/transactions'),api('/api/excavator/assets/'+id+'/documents'),api('/api/excavator/assets/'+id+'/history'),api('/api/excavator/assets/'+id+'/payments')]); const a=assets.find(x=>x.id==id); if(!a)return;
  const costTypes=['Purchase','Logistics','Repair','Part Purchase','Customs Duty','Tax / VAT','Shipping / Freight','Commission','Documentation / Clearance','Other Cost']; const costs=tx.filter(x=>costTypes.includes(x.type)&&x.status!=='Cancelled'); const totalCost=Number(a.total_cost||costs.reduce((n,x)=>n+Number(x.amount||0),0)); const sale=Number(a.sale_amount||0); const paid=Number(a.sale_paid||payments.filter(x=>x.payment_type==='Sale'&&x.status==='Paid').reduce((n,x)=>n+Number(x.amount||0),0)); const outstanding=Math.max(0,sale-paid); const profit=sale-totalCost; const pnlStatus=sale<=0?'Not Sold':(profit>=0?'Profit':'Loss'); const paymentStatus=a.sale_payment_status||(sale<=0?'Not Sold':outstanding<=0?'Paid':paid>0?'Partially Paid':'Pending');
  modal(`<div class="machine-header"><div><div class="muted">Machine / Deal</div><h2 style="margin:3px 0">${esc(a.asset_no)}</h2><div>${esc(a.machine_name||a.machine_display_name||((a.make||'')+' '+(a.model||'')))} · ${esc(a.type)}</div></div><span class="pill ${a.lifecycle_stage==='Sold / Completed'?'good':a.lifecycle_stage==='Sold / Payment Pending'?'warn':'blue'}">${esc(a.lifecycle_stage||'Purchased')}</span></div><div class="grid g4" style="margin:16px 0"><div class="card stat"><small>Purchase</small><b>₩ ${money(a.purchase_price)}</b></div><div class="card stat"><small>Total Cost</small><b>₩ ${money(totalCost)}</b></div><div class="card stat"><small>Sale</small><b>₩ ${money(sale)}</b></div><div class="card stat"><small>Profit / Loss</small><b class="${pnlStatus==='Profit'?'good':pnlStatus==='Loss'?'bad':''}">${pnlStatus==='Not Sold'?'—':`${pnlStatus}: ₩ ${money(Math.abs(profit))}`}</b></div></div><div class="card" style="margin-bottom:16px"><div class="section-title"><h3>Buyer Payment</h3><span class="pill ${paymentStatus==='Paid'?'good':paymentStatus==='Not Sold'?'blue':'warn'}">${esc(paymentStatus)}</span></div><div class="grid g3"><div><small>Sale Amount</small><b>₩ ${money(sale)}</b></div><div><small>Paid</small><b>₩ ${money(paid)}</b></div><div><small>Outstanding</small><b>₩ ${money(outstanding)}</b></div></div></div><div class="simple-actions">${a.lifecycle_stage==='Sold / Completed'&&me.role!=='CEO / Owner'?'':`<button class="btn primary" onclick="excavatorAddCost(${id})">+ Add Cost</button><button class="btn primary" onclick="excavatorSell(${id})">Sell Machine</button><button class="btn" onclick="excavatorPayments(${id})">Payments</button>`}<button class="btn" onclick="excavatorDocuments(${id})">Documents (${docs.length})</button><button class="btn" onclick="excavatorChangeStage(${id})">Status / Stage</button></div><div class="machine-sections"><div class="card"><div class="section-title"><h3>Purchase</h3><button class="btn small" onclick="excavatorEditMachine(${id})">Edit</button></div><div class="row"><span>Purchase date</span><b>${esc(a.purchase_date||'—')}</b></div><div class="row"><span>Price</span><b>₩ ${money(a.purchase_price)}</b></div><div class="row"><span>Seller / Supplier</span><b>${esc(a.supplier_name||((tx.find(x=>x.type==='Purchase')||{}).counterparty)||'—')}</b></div>${a.supplier_phone?`<div class="row"><span>Contact</span><b>${esc(a.supplier_phone)}</b></div>`:''}${a.supplier_location?`<div class="row"><span>Location</span><b>${esc(a.supplier_location)}</b></div>`:''}<div class="row"><span>Purchase Payment</span><b>${esc(a.purchase_status||'Pending')} · Paid ₩ ${money(a.purchase_paid||0)} · Balance ₩ ${money(a.purchase_outstanding||0)}</b></div></div><div class="card"><div class="section-title"><h3>Costs</h3><button class="btn small" onclick="excavatorAddCost(${id})">+ Add Cost</button></div>${costs.map(x=>`<div class="row"><span>${esc(x.type)}<small class="muted"> · ${esc(x.transaction_date||'')}</small></span><b>₩ ${money(x.amount)}</b></div>`).join('')||'<div class="muted">No additional costs yet.</div>'}<div class="row total"><span>Total machine cost</span><b>₩ ${money(totalCost)}</b></div></div><div class="card"><div class="section-title"><h3>Sale</h3><button class="btn small primary" onclick="excavatorSell(${id})">Sell Machine</button></div>${sale?`<div class="row"><span>Sale type</span><b>${esc((tx.find(x=>['Local Sale','Export Sale'].includes(x.type))||{}).type||'')}</b></div><div class="row"><span>Sale value</span><b>₩ ${money(sale)}</b></div><div class="row"><span>Customer</span><b>${esc(a.customer_name||'—')}</b></div><div class="row"><span>Payment status</span><b>${esc(paymentStatus)}</b></div>`:'<div class="muted">Machine has not been sold.</div>'}</div><div class="card"><div class="section-title"><h3>Recent History</h3></div>${hist.events.slice(0,8).map(x=>`<div class="row"><span>${esc(x.to_stage)}<small class="muted"> · ${esc(x.created_at)}</small></span><b>${esc(x.user_name||'')}</b></div>`).join('')||'<div class="muted">No stage changes yet.</div>'}</div></div>`)}

async function excavatorEditMachine(id){const a=(await api('/api/excavator/assets')).find(x=>x.id==id);if(!a)return;modal(`<h2>Edit Machine</h2><form onsubmit="saveExcavatorEdit(event,${id})"><div class="grid g3"><div class="field"><label>Machine / Deal No.</label><input name="asset_no" value="${esc(a.asset_no)}" required></div><div class="field"><label>Machine Name</label><input name="machine_name" value="${esc(a.machine_name||a.machine_display_name||"")}" required></div><div class="field"><label>Make</label><input name="make" value="${esc(a.make||'')}" required></div><div class="field"><label>Model</label><input name="model" value="${esc(a.model||'')}" required></div></div><div class="grid g3"><div class="field"><label>Year</label><input name="year" type="number" value="${a.year||''}"></div><div class="field"><label>Serial / Chassis</label><input name="serial_no" value="${esc(a.serial_no||'')}"></div><div class="field"><label>Purchase Price (KRW)</label><input name="purchase_price" type="number" step="1" value="${a.purchase_price||0}"></div></div><div class="field"><label>Notes</label><textarea name="notes">${esc(a.notes||'')}</textarea></div><div class="actions"><button type="button" class="btn" onclick="excavatorOpenMachine(${id})">Cancel</button><button class="btn primary">Save</button></div></form>`)}
async function saveExcavatorEdit(e,id){e.preventDefault();try{const o=Object.fromEntries(new FormData(e.target));await api('/api/excavator/assets/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});closeModal();excavatorOpenMachine(id)}catch(x){toast(x.message)}}
async function excavatorAddCost(id){
  modal(`<h2>Add Cost</h2><p class="muted">Add logistics, repair, parts, customs, tax, shipping, commission or other costs. You can attach multiple supporting documents.</p><form onsubmit="saveSimpleExcavatorCost(event,${id})" enctype="multipart/form-data"><div class="grid g2"><div class="field"><label>Cost Type</label><select name="type"><option>Logistics</option><option>Repair</option><option>Part Purchase</option><option>Customs Duty</option><option>Tax / VAT</option><option>Shipping / Freight</option><option>Commission</option><option>Documentation / Clearance</option><option>Other Cost</option></select></div><div class="field"><label>Amount (KRW)</label><input name="amount" type="number" min="0" step="1" required></div></div><div class="grid g2"><div class="field"><label>Date</label><input name="transaction_date" type="date" required></div><div class="field"><label>Include in Machine Cost?</label><select name="include_cost"><option value="1">Yes</option><option value="0">No — Business Expense</option></select></div></div><div class="field"><label>Supplier / Payee</label><input name="counterparty"></div><div class="field"><label>Description</label><textarea name="notes" placeholder="e.g. transport from seller to yard, customs duty, repair work..."></textarea></div><div class="field"><label>Attachments</label><input name="files" type="file" multiple></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save Cost</button></div></form>`)
}
async function saveSimpleExcavatorCost(e,id){
  e.preventDefault();
  try{
    const fd=new FormData(e.target);
    fd.append('stage','Costs');
    fd.append('currency','KRW');
    fd.append('status','Open');
    fd.append('include_in_machine_cost',fd.get('include_cost')==='1'?'1':'0');
    const r=await fetch('/api/excavator/assets/'+id+'/transactions',{method:'POST',headers:{Authorization:'Bearer '+token,'X-Business-Unit-ID':selectedUnitId||''},body:fd});
    const j=await r.json(); if(!r.ok)throw new Error(j.error||'Could not save cost');
    closeModal(); toast('Cost added'+(j.document_count?` with ${j.document_count} attachment(s)`:'')); excavatorOpenMachine(id);
  }catch(x){toast(x.message)}
}
async function excavatorSell(id){const [a,buyers]=await Promise.all([api('/api/excavator/assets'),api('/api/excavator/buyers')]);const machine=a.find(x=>x.id==id);if(!machine)return;const purchasePrice=Number(machine.purchase_price||0),purchasePaid=Number(machine.purchase_paid||0),outstanding=Math.max(0,purchasePrice-purchasePaid);if(outstanding>0){toast(`Cannot sell this machine until the complete purchase price is paid. Outstanding: ₩ ${money(outstanding)}`);return;}const today=new Date().toISOString().slice(0,10);modal(`<h2>Sell Machine · ${esc(machine.asset_no)}</h2><p class="muted">100% sale payment is taken in advance. Existing buyer advance will be allocated to this machine. A new buyer will be added automatically after sale completion.</p><form onsubmit="completeExcavatorSale(event,${id})"><div class="grid g2"><div class="field"><label>Sale Type *</label><select name="sale_type" required onchange="toggleExcavatorExportFields(this.value)"><option value="Local Sale">Local Sale</option><option value="Export Sale">Export Sale</option></select></div><div class="field"><label>Sale Date *</label><input name="sale_date" type="date" value="${today}" required></div></div><div class="field"><label>Buyer Record</label><select name="buyer_id" id="exBuyerSelect" onchange="fillExcavatorBuyer(this.value)"><option value="">+ New Buyer / Other</option>${buyers.map(b=>`<option value="${b.id}">${esc(b.name)} · ${esc(b.country||'')} · ${esc(b.buyer_type||'International')} · Available ₩ ${money(b.unallocated_advance_krw||0)}</option>`).join('')}</select></div><div id="exExistingBuyer" class="card" style="display:none"><div class="section-title"><h3>Selected Buyer Details</h3><span class="pill good" id="exBuyerBalance"></span></div><div class="grid g3"><div class="field"><label>Buyer / Company</label><input id="exExistingName" readonly></div><div class="field"><label>Buyer Type</label><input id="exExistingType" readonly></div><div class="field"><label>Country</label><input id="exExistingCountry" readonly></div><div class="field"><label>Location</label><input id="exExistingLocation" readonly></div><div class="field"><label>Contact Person</label><input id="exExistingContact" readonly></div><div class="field"><label>Phone</label><input id="exExistingPhone" readonly></div><div class="field"><label>WhatsApp</label><input id="exExistingWhatsapp" readonly></div><div class="field"><label>Email</label><input id="exExistingEmail" readonly></div><div class="field"><label>Address</label><input id="exExistingAddress" readonly></div></div></div><div id="exNewBuyer"><div class="grid g3"><div class="field"><label>Buyer / Company Name *</label><input name="new_buyer_name" id="exNewBuyerName"></div><div class="field"><label>Buyer Type *</label><select name="new_buyer_type"><option>International</option><option>Local</option></select></div><div class="field"><label>Country *</label><input name="new_buyer_country" id="exNewBuyerCountry"></div><div class="field"><label>Location / City</label><input name="new_buyer_location"></div><div class="field"><label>Contact Person</label><input name="new_buyer_contact_person"></div><div class="field"><label>Phone</label><input name="new_buyer_phone"></div><div class="field"><label>WhatsApp</label><input name="new_buyer_whatsapp"></div><div class="field"><label>Email</label><input name="new_buyer_email" type="email"></div><div class="field"><label>Payment Terms</label><input name="new_buyer_payment_terms"></div></div><div class="field"><label>Address</label><textarea name="new_buyer_address"></textarea></div><div class="field"><label>Notes</label><textarea name="new_buyer_notes"></textarea></div></div><div class="grid g2"><div class="field"><label>Customer / Buyer *</label><input id="exCustomerName" name="customer_name" placeholder="Customer / company name" required></div><div class="field"><label>Selling Price (KRW) *</label><input name="selling_price" type="number" min="1" step="1" required value="${machine.selling_price||0}"></div></div><div id="exExportFields" style="display:none"><div class="grid g2"><div class="field"><label>Destination Country *</label><select name="destination_country" onchange="toggleOtherDestination(this.value)"><option value="Pakistan">Pakistan</option><option value="__OTHER__">Other Country</option></select></div><div class="field" id="exOtherCountryWrap" style="display:none"><label>Other Destination Country *</label><input name="other_destination_country"></div></div></div><div class="grid g2"><div class="field"><label>Shipping / Container Reference *</label><input name="shipping_reference" required></div><div class="field"><label>Payment Method *</label><select name="payment_method" required><option>Bank</option><option>Cash</option><option>Card</option><option>Other</option></select></div></div><div class="grid g3"><div class="field"><label>Payment Currency *</label><select name="payment_currency"><option>KRW</option><option>USD</option><option>PKR</option></select></div><div class="field"><label>Conversion Rate to KRW *</label><input name="payment_fx_rate" type="number" step="0.000001" min="0.000001" value="1" required></div><div class="field"><label>Payment Date *</label><input name="payment_date" type="date" value="${today}" required></div></div><div class="field"><label>Payment Reference *</label><input name="payment_reference" required autocomplete="off"></div><div class="field"><label>Notes (optional)</label><textarea name="notes"></textarea></div><div class="field"><label>Sell Note (optional)</label><textarea name="sell_note"></textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button type="submit" class="btn primary">Complete Sale</button></div></form>`);toggleExcavatorExportFields('Local Sale');fillExcavatorBuyer('');}
async function fillExcavatorBuyer(id){const wrap=document.getElementById('exExistingBuyer'),nw=document.getElementById('exNewBuyer'),name=document.getElementById('exCustomerName');if(!id){if(wrap)wrap.style.display='none';if(nw)nw.style.display='block';if(name)name.value='';return;}try{const d=await api('/api/excavator/buyers/'+id),b=d.buyer;if(wrap)wrap.style.display='block';if(nw)nw.style.display='none';if(name)name.value=b.name;const set=(id,v)=>{const el=document.getElementById(id);if(el)el.value=v||''};set('exExistingName',b.name);set('exExistingType',b.buyer_type||'International');set('exExistingCountry',b.country);set('exExistingLocation',b.location);set('exExistingContact',b.contact_person);set('exExistingPhone',b.phone);set('exExistingWhatsapp',b.whatsapp);set('exExistingEmail',b.email);set('exExistingAddress',b.address);const bal=document.getElementById('exBuyerBalance');if(bal)bal.textContent=`Available advance: ₩ ${money(d.balance.available_advance_krw)}`;}catch(e){toast(e.message)}}
function toggleExcavatorExportFields(value){const wrap=document.getElementById('exExportFields'),country=document.querySelector('[name="destination_country"]'),other=document.querySelector('[name="other_destination_country"]');if(wrap)wrap.style.display=value==='Export Sale'?'block':'none';if(country)country.required=value==='Export Sale';if(value!=='Export Sale'&&other){other.value='';other.required=false;}}
function toggleOtherDestination(value){const w=document.getElementById('exOtherCountryWrap'),other=document.querySelector('[name="other_destination_country"]');if(w)w.style.display=value==='__OTHER__'?'block':'none';if(other)other.required=value==='__OTHER__';}
async function completeExcavatorSale(e,id){e.preventDefault();const form=e.target;if(!form.reportValidity())return;try{const fd=new FormData(form),o=Object.fromEntries(fd.entries());for(const k of Object.keys(o))if(typeof o[k]==='string')o[k]=o[k].trim();o.destination_country=o.sale_type==='Export Sale'?(o.destination_country==='__OTHER__'?o.other_destination_country:o.destination_country):'';if(!o.customer_name)throw new Error('Customer / Buyer is required.');const price=Number(o.selling_price);if(!Number.isFinite(price)||price<=0)throw new Error('Selling Price must be greater than zero.');if(!o.buyer_id){o.new_buyer_name=o.new_buyer_name||o.customer_name;o.new_buyer_country=o.new_buyer_country||o.destination_country;if(!o.new_buyer_name||!o.new_buyer_country)throw new Error('Complete new buyer name and country are required.');}const r=await api('/api/excavator/assets/'+id+'/complete-sale',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});closeModal();toast(r.document_url?'Sale recorded · Buyer updated · Sale PDF added to Documents':'Sale recorded');loadView();if(r.document_url)setTimeout(()=>window.open(r.document_url,'_blank'),250);}catch(x){toast(x.message)}}
async function excavatorChangeStage(id){const a=(await api('/api/excavator/assets')).find(x=>x.id==id);modal(`<h2>Machine Status</h2><form onsubmit="saveSimpleStage(event,${id})"><div class="field"><label>Current stage</label><select name="stage">${['Purchased','Transport to Yard','In Yard','Under Repair','Ready for Sale','On Hold','Export Preparation','Cancelled'].map(x=>`<option ${a?.lifecycle_stage===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Note</label><textarea name="note"></textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save Status</button></div></form>`)}
