  if(!confirm('Delete this payment record?'))return;
  try{await api('/api/excavator/assets/'+assetId+'/payments/'+paymentId,{method:'DELETE'});toast('Payment deleted');excavatorPayments(assetId)}catch(x){toast(x.message)}
