async function excavatorPaymentForm(id){modal(`<h2>Add Payment</h2><form onsubmit="saveExcavatorPayment(event,${id})" enctype="multipart/form-data"><div class="grid g3"><div class="field"><label>Payment For</label><select name="payment_type"><option>Purchase</option><option>Sale</option></select></div><div class="field"><label>Amount (KRW)</label><input name="amount" type="number" min="0" step="1" required></div><div class="field"><label>Payment Date</label><input name="payment_date" type="date" required></div></div><div class="grid g3"><div class="field"><label>Method</label><select name="method"><option>Bank</option><option>Cash</option><option>Card</option><option>Other</option></select></div><div class="field"><label>Reference</label><input name="reference" required placeholder="Required"></div><div class="field"><label>Payment Receipt</label><input name="receipt" type="file" multiple accept="application/pdf,image/*"></div></div><div class="field"><label>Notes</label><textarea name="notes"></textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save Payment</button></div></form>`)}
async function saveExcavatorPayment(e,id){e.preventDefault();try{const fd=new FormData(e.target);if(!fd.get('payment_date'))throw new Error('Payment Date is required.');if(!String(fd.get('reference')||'').trim())throw new Error('Reference is required.');const r=await fetch('/api/excavator/assets/'+id+'/payments',{method:'POST',headers:{Authorization:'Bearer '+token,'X-Business-Unit-ID':selectedUnitId||''},body:fd});const j=await r.json();if(!r.ok)throw new Error(j.error||'Payment could not be saved');toast(j.receipt_document_id?'Payment saved and receipt added to Documents':'Payment saved');excavatorPayments(id)}catch(x){toast(x.message)}}

async function excavatorDocuments(id){const docs=await api('/api/excavator/assets/'+id+'/documents');modal(`<h2>Documents</h2><p class="muted">Attach multiple files now or later. Previous documents are never replaced.</p><form onsubmit="uploadExcavatorDocuments(event,${id})" enctype="multipart/form-data"><div class="grid g2"><div class="field"><label>Stage</label><select name="stage">${['Purchase','Costs','Repair','Parts','Local Sale','Export Preparation','Export/Shipping','Payment','General'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Files</label><input name="files" type="file" multiple required></div></div><div class="actions"><button class="btn primary">Upload Documents</button></div></form><div class="table-wrap" style="margin-top:12px"><table class="table"><tr><th>Stage</th><th>File</th><th>Date</th><th>Open</th></tr>${docs.map(d=>`<tr><td>${esc(d.stage)}</td><td>${esc(d.original_name)}</td><td>${esc(d.created_at)}</td><td><a class="btn small" href="${esc(d.file_path)}" target="_blank">Open</a></td></tr>`).join('')||'<tr><td colspan="4">No documents yet.</td></tr>'}</table></div>`)}
