async function restaurantPOS(){const [p,t]=await Promise.all([api('/api/products'),api('/api/restaurant/tables')]);const menu=p.filter(x=>x.business_unit==='MIMI Resturant');window._rItems=[];modal(`<div class="section-title"><h2>MIMI Resturant POS</h2></div><div class="pos-layout"><div><div class="grid g3"><div class="field"><label>Order type</label><select id="rType"><option>Dine-in</option><option>Takeaway</option><option>Delivery</option></select></div><div class="field"><label>Table</label><select id="rTable"><option value="">No table</option>${t.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Customer</label><input id="rCustomer"></div></div><div class="menu-grid">${menu.map(x=>`<button type="button" class="menu-item" onclick="addRItem(${x.id})"><b>${esc(x.name)}</b><div class="muted">${x.item_type} · ${money(x.selling_price)}</div></button>`).join('')}</div></div><div class="card"><h3>Order</h3><div id="rCart"></div><div class="field"><label>Payment</label><select id="rPayment"><option>Cash</option><option>Card</option><option>Bank</option><option>Credit</option></select></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveROrder()">Close & Pay</button></div></div></div>`);window._rProducts=menu;drawR()}
function addRItem(id){const p=window._rProducts.find(x=>x.id==id),x=window._rItems.find(x=>x.product_id==id);if(x)x.quantity++;else window._rItems.push({product_id:p.id,name:p.name,quantity:1,unit_price:p.selling_price});drawR()}
function drawR(){const e=document.getElementById('rCart');if(!e)return;e.innerHTML=window._rItems.length?window._rItems.map((x,i)=>`<div class="cart-row"><span>${esc(x.name)}</span><span><input style="width:55px" type="number" min="0.01" step="0.01" value="${x.quantity}" onchange="window._rItems[${i}].quantity=Number(this.value);drawR()"> × <input style="width:85px" type="number" min="0" step="0.01" value="${x.unit_price}" onchange="window._rItems[${i}].unit_price=Number(this.value);drawR()"> = <b>${money(x.quantity*x.unit_price)}</b> <button class="btn small" onclick="window._rItems.splice(${i},1);drawR()">×</button></span></div>`).join(''):'<span class="muted">Empty order</span>'}
async function saveROrder(){if(!window._rItems.length)return toast('Add menu items');try{const d=await api('/api/restaurant/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({table_id:document.getElementById('rTable').value,order_type:document.getElementById('rType').value,customer_name:document.getElementById('rCustomer').value,items:window._rItems})});const pay=document.getElementById('rPayment').value;await api('/api/restaurant/orders/'+d.id+'/close',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({payment_method:pay})});closeModal();toast('MIMI order closed and posted to sales/finance/inventory');loadView();printReceipt(d.id)}catch(x){toast(x.message)}}
async function manageRestaurantTables(){try{const t=await api('/api/restaurant/tables');modal(`<div class="section-title"><h2>MIMI Tables</h2><button class="btn primary" onclick="tableForm()">+ Add Table</button></div><p class="muted">Delete Table is available for tables that are not Busy and have no open order.</p><div class="table-wrap"><table class="table"><tr><th>Table</th><th>Capacity</th><th>Status</th><th>Actions</th></tr>${t.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.capacity}</td><td><span class="pill ${x.status==='Available'?'good':x.status==='Busy'?'bad':'warn'}">${esc(x.status)}</span></td><td><button class="btn small" onclick="tableForm(${x.id})">Edit</button> <button class="btn small danger" onclick="deleteTable(${x.id},true)">Delete Table</button></td></tr>`).join('')}</table></div>${!t.length?'<p class="muted">No restaurant tables configured.</p>':''}`)}catch(x){toast(x.message)}}

async function tableForm(id){const t=id?(await api('/api/restaurant/tables')).find(x=>x.id==id):null;modal(`<h2>${id?'Edit':'Add'} restaurant table</h2><form onsubmit="saveTable(event,${id||0})"><div class="grid g2"><div class="field"><label>Table name</label><input name="name" value="${esc(t?.name||'')}" required></div><div class="field"><label>Capacity</label><input name="capacity" type="number" value="${t?.capacity||4}"></div></div><div class="field"><label>Status</label><select name="status"><option ${t?.status==='Available'?'selected':''}>Available</option><option ${t?.status==='Busy'?'selected':''}>Busy</option><option ${t?.status==='Reserved'?'selected':''}>Reserved</option></select></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">${id?'Update':'Add'}</button></div></form>`)}
async function saveTable(e,id){e.preventDefault();try{await api(id?'/api/restaurant/tables/'+id:'/api/restaurant/tables',{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();loadView()}catch(x){toast(x.message)}}
async function deleteTable(id,fromManager=false){if(!confirm('Delete this table?'))return;try{await api('/api/restaurant/tables/'+id,{method:'DELETE'});toast('Table deleted');if(fromManager)manageRestaurantTables();else loadView()}catch(x){toast(x.message)}}
async function wasteForm(){const p=(await api('/api/products')).filter(x=>x.business_unit==='MIMI Resturant'&&x.item_type==='PRODUCT');modal(`<h2>MIMI waste</h2><form onsubmit="saveWaste(event)"><div class="field"><label>Item</label><select name="product_id">${p.map(x=>`<option value="${x.id}">${esc(x.name)} (${x.current_stock})</option>`).join('')}</select></div><div class="field"><label>Quantity</label><input name="quantity" type="number" step="0.01" required></div><div class="field"><label>Reason</label><input name="reason" placeholder="Spoilage, damage, expired..."></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Record waste</button></div></form>`)}
async function saveWaste(e){e.preventDefault();try{await api('/api/restaurant/waste',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast('Waste recorded and inventory reduced');loadView()}catch(x){toast(x.message)}}
function closingForm(){modal(`<h2>MIMI daily closing</h2><form onsubmit="saveClosing(event)"><div class="grid g2"><div class="field"><label>Business date</label><input name="business_date" type="date" value="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label>Cash counted</label><input name="cash_counted" type="number" step="0.01"></div></div><div class="field"><label>Notes</label><textarea name="notes"></textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Close day</button></div></form>`)}
async function saveClosing(e){e.preventDefault();try{const d=await api('/api/restaurant/closing',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast(`Day closed · Cash variance ${money(d.variance)}`)}catch(x){toast(x.message)}}
async function toggleNotifs(){const n=await api('/api/notifications');document.querySelector('.notif-panel')?.remove();const d=document.createElement('div');d.className='notif-panel';d.innerHTML='<b>Notifications & Alerts</b>'+ (n.length?n.map(x=>`<div class="notif"><span class="pill ${x.level==='critical'?'bad':x.level==='warning'?'warn':'blue'}">${x.level}</span> <b>${esc(x.title)}</b><div class="muted">${esc(x.message)}</div>${!x.read_at?`<button class="btn small" onclick="readNotif(${x.id})">Mark read</button>`:''}</div>`).join(''):'<p class="muted">No notifications</p>');document.body.appendChild(d)}
async function readNotif(id){await api('/api/notifications/'+id+'/read',{method:'PUT'});toggleNotifs()}
async function printReceipt(id){try{const s=await api('/api/sales/'+id);const w=window.open('','_blank','width=420,height=700');if(!w)return toast('Please allow pop-ups to print the receipt');w.document.write(`<html><head><title>${esc(s.invoice_no)}</title><style>body{font-family:Arial,sans-serif;width:80mm;margin:0;padding:12px;font-size:12px}h2{text-align:center;margin:0 0 4px}.center{text-align:center}.line{border-top:1px dashed #333;margin:8px 0}.row{display:flex;justify-content:space-between;margin:4px 0}.total{font-size:16px;font-weight:bold}.muted{color:#666}.empty{padding:28px;text-align:center;color:#64748b}.notif{padding:12px;border:1px solid #e2e8f0;border-radius:10px} .stat .value{font-size:28px;font-weight:800}</style></head><body><h2>BLUE OCEAN MARKET</h2><div class=center>${esc(s.business_unit)}</div><div class=center>${esc(s.invoice_no)} · ${esc(s.created_at)}</div><div class=line></div>${s.items.map(i=>`<div class=row><span>${esc(i.item_name)} × ${i.quantity}</span><span>${money(i.line_total)}</span></div>`).join('')}<div class=line></div><div class=row><span>Subtotal</span><span>${money(s.subtotal)}</span></div><div class=row><span>Discount</span><span>${money(s.discount)}</span></div><div class=row><span>Tax</span><span>${money(s.tax)}</span></div><div class=row total><span>Total</span><span>${money(s.total)}</span></div><div class=row><span>Payment</span><span>${esc(s.payment_method)}</span></div><div class=line></div><div class=center>Thank you</div><script>window.onload=()=>{window.print();setTimeout(()=>window.close(),500)}<\/script></body></html>`);w.document.close()}catch(x){toast(x.message)}}

async function purchaseEdit(id){const rows=await api('/api/purchases'),x=rows.find(z=>z.id==id);if(!x)return;modal(`<h2>Edit purchase</h2><form onsubmit="savePurchaseEdit(event,${id})"><div class="field"><label>Supplier</label><input name="supplier_name" value="${esc(x.supplier_name||'')}"></div><div class="grid g2"><div class="field"><label>Payment</label><select name="payment_method"><option>Cash</option><option>Card</option><option>Bank</option><option>Credit</option></select></div><div class="field"><label>Status</label><select name="status"><option>Posted</option><option>Voided</option></select></div></div><div class="field"><label>Notes</label><textarea name="notes">${esc(x.notes||'')}</textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Update</button></div></form>`)}
