async function saveFinanceEdit(e,id){e.preventDefault();try{await api('/api/finance/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast('Finance updated');loadView()}catch(x){toast(x.message)}}
