async function crmEdit(id){const rows=await api('/api/crm'),x=rows.find(z=>z.id==id),u=await api('/api/business-units');modal(`<h2>Edit CRM record</h2><form onsubmit="saveCRMEdit(event,${id})"><div class="grid g2"><div class="field"><label>Company / Customer</label><input name="company" value="${esc(x.company)}" required></div><div class="field"><label>Contact</label><input name="contact" value="${esc(x.contact||'')}"></div></div><div class="grid g3"><div class="field"><label>Stage</label><select name="stage">${['Lead','Contacted','Qualified','Quotation','Negotiation','Won','Lost'].map(z=>`<option ${x.stage===z?'selected':''}>${z}</option>`).join('')}</select></div><div class="field"><label>Potential value</label><input name="potential_value" type="number" value="${x.potential_value||0}"></div><div class="field"><label>Follow-up</label><input name="next_followup" type="date" value="${x.next_followup||''}"></div></div><div class="field"><label>Business</label><select name="business_unit_id"><option value="">Company</option>${u.map(z=>`<option value="${z.id}" ${x.business_unit_id==z.id?'selected':''}>${esc(z.name)}</option>`).join('')}</select></div><div class="field"><label>Notes</label><textarea name="notes">${esc(x.notes||'')}</textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Update</button></div></form>`)}
