async function kpiEdit(id){const rows=await api('/api/kpis'),u=await api('/api/users'),b=await api('/api/business-units'),x=rows.find(z=>z.id==id);modal(`<h2>Edit KPI</h2><form onsubmit="saveKPIEdit(event,${id})"><div class="field"><label>Name</label><input name="name" value="${esc(x.name)}" required></div><div class="grid g2"><div class="field"><label>Target</label><input name="target" type="number" value="${x.target}"></div><div class="field"><label>Actual</label><input name="actual" type="number" value="${x.actual}"></div></div><div class="grid g2"><div class="field"><label>User</label><select name="user_id"><option value="">Company / Unit</option>${u.map(z=>`<option value="${z.id}" ${x.user_id==z.id?'selected':''}>${esc(z.name)}</option>`).join('')}</select></div><div class="field"><label>Business</label><select name="business_unit_id"><option value="">Company</option>${b.map(z=>`<option value="${z.id}" ${x.business_unit_id==z.id?'selected':''}>${esc(z.name)}</option>`).join('')}</select></div></div><div class="field"><label>Period</label><input name="period" value="${esc(x.period||'Monthly')}"></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Update</button></div></form>`)}
async function saveKPIEdit(e,id){e.preventDefault();try{await api('/api/kpis/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast('KPI updated');loadView()}catch(x){toast(x.message)}}
