async function userEdit(id){const [rows,b]=await Promise.all([api('/api/users'),api('/api/business-units')]);const x=rows.find(z=>z.id==id);modal(`<h2>Edit user</h2><form onsubmit="saveUserEdit(event,${id})"><div class="field"><label>Name</label><input name="name" value="${esc(x.name)}" required></div><div class="field"><label>Email</label><input name="email" value="${esc(x.email)}" required></div><div class="grid g2"><div class="field"><label>Role</label><select name="role">${roles.map(r=>`<option ${x.role===r?'selected':''}>${r}</option>`).join('')}</select></div><div class="field"><label>Business</label><select name="business_unit_id"><option value="">All / Company</option>${b.map(z=>`<option value="${z.id}" ${x.business_unit_id==z.id?'selected':''}>${esc(z.name)}</option>`).join('')}</select></div></div><div class="field"><label>New password (optional)</label><input name="password" type="password"></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Update</button></div></form>`)}
