async function userDeactivate(id){if(!confirm('Deactivate this user? The user will remain assigned to the same business and can be activated later.'))return;try{await api('/api/users/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({active:0})});toast('User deactivated; business assignment preserved');loadView()}catch(x){toast(x.message)}}
